"""Bounded, event-driven crop contracts on the unchanged Boss Response routes.

Appended to baseline.py by build.py. Standard library only. Worker movement,
animal infrastructure and existing livestock remain owned by the baseline.
Every crop contract is checked against future service visits before purchase.
"""
DB_ENABLED = True
DB_SHADOW = False
DB_MAX_SITES = 4
DB_MIN_GAIN = 12.0
DB_CASH_RESERVE = 1500
DB_START = 192
DB_CROPS = ('WHEAT', 'CARROT', 'TOMATO', 'STRAWBERRY', 'MELON')
_DB_SPEC = {'WHEAT': (10, 4, 4), 'CARROT': (20, 3, 3),
            'TOMATO': (50, 11, 4), 'STRAWBERRY': (100, 16, 4), 'MELON': (80, 10, 6)}
_DB_STATE = {}
_DB_REPORT = {}
_DB_PARENT = agent
del agent


def _db_log(kind, **values):
    _DB_REPORT[kind] = _DB_REPORT.get(kind, 0) + 1
    if len(_DB_REPORT.setdefault('events', [])) < 500:
        _DB_REPORT['events'].append(dict(kind=kind, **values))


def _db_visits(obs, action):
    """Projected baseline visits, never hidden game state or future shop draws."""
    farm = obs['farms'][int(obs['player'])]
    board = len(farm['tiles']); step = int(obs['step'])
    positions = [list(farm['farmer'])] + [list(p) for p in farm['hands']]
    out = {}
    for t in range(step, 719):
        act = action if t == step else _ca_tape(int(obs['player']), t)
        cmds = [act.get('farmer') or ['PASS']] + list(act.get('hands') or [])
        for i, pos in enumerate(positions):
            cmd = cmds[i] if i < len(cmds) and cmds[i] else ['PASS']
            if cmd[0] in _CA_MOVES:
                dx, dy = _CA_MOVES[cmd[0]]
                if 0 <= pos[0] + dx < board and 0 <= pos[1] + dy < board:
                    positions[i] = [pos[0] + dx, pos[1] + dy]
            else:
                out.setdefault(tuple(pos), []).append((t, i, cmd[0]))
        for order in act.get('market') or []:
            if order and order[0] == 'HIRE':
                positions.append(_ca_spawn(positions, board))
        if t % 24 == 23:
            positions = [[board // 2 - 1, board // 2 - 1]]
    return out


def _db_schedule(crop, visits, earliest):
    """Require planting, same-day water, daily water and timely harvest slots.

    The final harvest is before day 29 so the overnight deposit can be sold.
    Multiple workers on the same turn are ordered by their actual unit index.
    """
    cost, duration, quantity = _DB_SPEC[crop]
    usable = [(t, i, op) for t, i, op in visits if t >= earliest]
    for start, unit, op in usable[:10]:
        if start > earliest + 24 or start // 24 + duration > 28:
            break
        if op not in ('PASS', 'PLANT', 'WATER', 'HARVEST', 'FERTILIZE', 'DIG'):
            continue
        born = start // 24; finish = born + duration
        during = [(t, i, op) for t, i, op in usable if (t, i) > (start, unit) and t // 24 <= finish]
        if any(op in ('BUILD_COOP', 'BUILD_PASTURE', 'PLACE') for t, i, op in during):
            continue
        slots = {}
        for t, i, op in during:
            if op in ('PASS', 'PLANT', 'WATER', 'HARVEST', 'FERTILIZE', 'DIG'):
                slots.setdefault(t // 24, []).append((t, i))
        if not all(slots.get(d) for d in range(born, finish + 1)):
            continue
        harvest_days = ([born + d for d in (8, 9, 10, 11)] if crop == 'TOMATO' else
                        [born + d for d in (10, 12, 14, 16)] if crop == 'STRAWBERRY' else [finish])
        if any(len(slots[d]) < 2 for d in harvest_days):
            continue
        return dict(crop=crop, start=start, start_unit=unit, born=born, finish=finish,
                    harvest_days=harvest_days, quantity=quantity, cost=cost,
                    harvest_step=slots[finish][1][0])
    return None


def _db_quote(obs, crop, plan, st):
    """Conservative public supply/demand scenarios, including committed batches."""
    day = int(obs['step']) // 24
    market = obs['market']; params = _at_params(obs)
    inventory = float(market['inventory'][crop])
    shops = obs.get('town', {}).get('unlocked_shops', [])
    demand = _hd2_daily_shop_demand(crop, shops) + 1.
    visible = 0.
    for farm in obs['farms']:
        for row in farm['tiles']:
            for tile in row:
                if isinstance(tile, dict) and tile.get('crop') == crop:
                    visible += _DB_SPEC[crop][2] / max(3., _DB_SPEC[crop][1])
    pending = sum(p['quantity'] for p in st['sites'].values()
                  if p['crop'] == crop and p['status'] == 'pending')
    horizons = [d - day + 1 for d in plan['harvest_days']]
    values = []
    for horizon in horizons:
        # Do not assume new shops or perfect future scarcity. Extra supply is
        # priced into both scenarios, including this batch's market impact.
        inv = inventory + pending + plan['quantity'] + (visible - demand) * horizon
        projected = _r37_market_price(crop, int(inv), params)
        current = float(market['prices'][crop])
        values.append(min(projected, current * 1.3))
    revenue = sum(values) * plan['quantity'] / len(values) * .85
    profit = revenue - plan['cost']
    plan.update(profit=round(profit, 3), score=round(profit / (plan['finish'] - plan['born'] + 1), 3))
    return plan


def _db_reserve(obs, action):
    farm = obs['farms'][int(obs['player'])]
    animals = sum(bool(isinstance(t, dict) and t.get('animal')) for row in farm['tiles'] for t in row)
    wheat = _ca_wheat_total(obs)
    feed = max(0, animals * 3 - wheat) * float(obs['market']['prices']['WHEAT'])
    # Cover current orders without counting unconfirmed sales proceeds.
    orders_cost = 0.; hires = int(farm.get('hires_today', 0))
    for order in action.get('market', []):
        if not order:
            continue
        op = order[0]
        if op == 'HIRE':
            orders_cost += _fib(hires + 1); hires += 1
        elif op == 'BUY_LAND':
            orders_cost += (1000, 2000, 4000, 8000)[min(3, len(farm.get('unlocked_quadrants', [])) - 1)]
        elif len(order) >= 3 and op == 'BUY_SEED':
            orders_cost += max(0, int(order[2])) * _DB_SPEC.get(order[1], (100,))[0]
        elif len(order) >= 3 and op in ('BUY_PRODUCT', 'BUY_ANIMAL'):
            price = {'GOOSE': 300, 'COW': 400, 'SHEEP': 500}.get(order[1], obs['market']['prices'].get(order[1], 100))
            orders_cost += max(0, int(order[2])) * float(price) * 1.1
    return DB_CASH_RESERVE + feed + orders_cost


def _db_reconcile(obs, st):
    step = int(obs['step']); farm = obs['farms'][int(obs['player'])]
    for pos, plan in list(st['sites'].items()):
        tile = farm['tiles'][pos[1]][pos[0]]
        matches = isinstance(tile, dict) and tile.get('crop') == plan['crop'] and tile.get('planted_day') == plan.get('planted_day')
        if plan['status'] == 'plant_sent':
            if matches:
                plan['status'] = 'growing'
                _db_log('planted', step=step, pos=pos, crop=plan['crop'])
            else:
                plan['status'] = 'pending'
        if plan['status'] == 'growing' and not matches:
            _db_log('released' if tile is None and plan.get('harvest_sent') == step - 1 else 'lost', step=step, pos=pos, crop=plan['crop'])
            del st['sites'][pos]
        elif plan['status'] == 'pending' and (step > plan['start'] + 24 or tile is not None):
            _db_log('cancelled', step=step, pos=pos, crop=plan['crop'])
            del st['sites'][pos]


def _db_plan(obs, action, st):
    step = int(obs['step']); farm = obs['farms'][int(obs['player'])]
    cash = float(farm['money'])
    free = tuple((x, y) for y, row in enumerate(farm['tiles']) for x, tile in enumerate(row) if tile is None)
    signature = (step // 24, free, int(cash // 500), tuple(obs.get('town', {}).get('unlocked_shops', [])))
    if signature == st.get('signature') or step - st.get('last_plan', -100) < 6:
        return
    st['signature'] = signature; st['last_plan'] = step
    if step < DB_START or step >= 648 or len(st['sites']) >= DB_MAX_SITES:
        return
    if cash < _db_reserve(obs, action) + 100 or len(action.get('market', [])) >= 9:
        return
    visits = _db_visits(obs, action)
    candidates = []
    for pos in free:
        if pos in st['sites']:
            continue
        path = visits.get(pos, [])
        # Only existing crop circuits: never appropriate an animal site or
        # attempt expansion onto a tile the baseline workers do not service.
        if not any(step <= t <= step + 24 and op == 'PLANT' for t, i, op in path):
            continue
        choices = []
        for crop in DB_CROPS:
            plan = _db_schedule(crop, path, step + 1)
            if plan:
                choices.append(_db_quote(obs, crop, plan, st))
        if not choices:
            continue
        best = max(choices, key=lambda p: p['score'])
        # Require an advantage over either short-cycle alternative; the
        # baseline already has a strong wheat/carrot selector.
        short = max((p['score'] for p in choices if p['crop'] in ('WHEAT', 'CARROT')), default=0.)
        if best['crop'] in ('WHEAT', 'CARROT') or best['score'] < short + DB_MIN_GAIN:
            continue
        candidates.append((best['score'] - short, pos, best, choices))
    for gain, pos, best, choices in sorted(candidates, reverse=True):
        if len(st['sites']) >= DB_MAX_SITES or len(action['market']) >= 10:
            break
        if cash < _db_reserve(obs, action) + best['cost']:
            break
        _db_log('decision', step=step, pos=pos, choice=best['crop'], gain=round(gain, 3), candidates=choices)
        if DB_SHADOW:
            continue
        plan = dict(best, status='pending', bought_step=step)
        st['sites'][pos] = plan
        # Purchases are requests only; PLANT checks the next observation's
        # real seed balance. Never consume a same-turn expected receipt.
        action['market'].append(['BUY_SEED', best['crop'], 1])
        cash -= best['cost']


def _db_execute(obs, action, st):
    step = int(obs['step']); day = step // 24
    farm = obs['farms'][int(obs['player'])]; private = obs['private']
    positions = [tuple(farm['farmer'])] + [tuple(p) for p in farm['hands']]
    units = [list(action.get('farmer') or ['PASS'])] + [list(c or ['PASS']) for c in action.get('hands', [])]
    units += [['PASS'] for _ in range(len(positions) - len(units))]
    seeds = dict(private['seeds']); planted = set(); watered = set(); harvested = set()
    for i, (pos, cmd) in enumerate(zip(positions, units)):
        if pos not in st['sites'] and cmd[0] == 'PLANT' and len(cmd) > 1:
            seeds[cmd[1]] = seeds.get(cmd[1], 0) - 1
    for i, (pos, cmd) in enumerate(zip(positions, units)):
        plan = st['sites'].get(pos)
        if plan is None or cmd[0] in _CA_MOVES or cmd[0] in ('DROP', 'PICKUP', 'PLACE', 'FEED', 'CARE', 'COLLECT_FERTILIZER'):
            continue
        tile = farm['tiles'][pos[1]][pos[0]]
        crop = plan['crop']; new = ['PASS']
        if pos in planted and pos not in watered:
            new = ['WATER']; watered.add(pos)
        elif tile is None and plan['status'] == 'pending' and pos not in planted:
            if (step, i) < (plan['start'], plan['start_unit']):
                units[i] = ['PASS']
                continue
            if seeds.get(crop, 0) > 0:
                # Recheck today's actual position before planting; one later
                # service visit is mandatory for the first watering.
                visits = _ca_visits(obs, action, pos, day * 24 + 23, start=step)
                if any((t, j) > (step, i) and op in ('PASS', 'PLANT', 'WATER', 'HARVEST', 'FERTILIZE', 'DIG') for t, j, op in visits):
                    new = ['PLANT', crop]; seeds[crop] -= 1; planted.add(pos)
                    plan.update(status='plant_sent', planted_day=day)
        elif isinstance(tile, dict) and tile.get('crop') == crop:
            age = day - int(tile['planted_day'])
            if not tile.get('watered_today') and pos not in watered:
                new = ['WATER']; watered.add(pos)
            elif pos not in harvested and tile.get('yield_units', 0) > 0:
                mature = age >= _DB_SPEC[crop][1] if crop not in ('TOMATO', 'STRAWBERRY') else age >= (8 if crop == 'TOMATO' else 10)
                if mature:
                    new = ['HARVEST']; harvested.add(pos)
                    plan['harvest_sent'] = step
                    _db_log('harvest_requested', step=step, crop=crop, quantity=tile['yield_units'])
            elif crop in ('TOMATO', 'STRAWBERRY') and age >= _DB_SPEC[crop][1] and not tile.get('yield_units'):
                new = ['DIG']; plan['harvest_sent'] = step
        if new != cmd:
            units[i] = new
            _DB_REPORT['unit_overrides'] = _DB_REPORT.get('unit_overrides', 0) + 1
    action['farmer'] = units[0]; action['hands'] = units[1:]
    # Only sell surplus actually in the shed; baseline receipts/order ranking
    # remain authoritative for already scheduled sales. No fictitious credit.
    products = {p['crop'] for p in st['sites'].values()} | st['products']
    st['products'].update(products)
    for crop in sorted(products):
        if crop == 'WHEAT':
            continue
        existing = sum(int(o[2]) for o in action['market'] if len(o) >= 3 and o[:2] == ['SELL', crop])
        qty = max(0, int(private['shed'].get(crop, 0)) - existing)
        if qty and len(action['market']) < 10:
            action['market'].append(['SELL', crop, qty])


def agent(observation, configuration=None):
    action = _DB_PARENT(observation, configuration)
    if not DB_ENABLED:
        return action
    step = int(observation['step']); seat = int(observation['player'])
    st = _DB_STATE.get(seat)
    if st is None or step <= st['step']:
        st = _DB_STATE[seat] = dict(step=-1, sites={}, products=set())
        _DB_REPORT.clear()
    st['step'] = step
    # Isolated copies prevent accidental mutation of the baseline action tape.
    result = dict(action, farmer=list(action.get('farmer') or ['PASS']),
                  hands=[list(c) for c in action.get('hands', [])],
                  market=[list(o) for o in action.get('market', [])])
    _db_reconcile(observation, st)
    _db_plan(observation, result, st)
    if DB_SHADOW:
        return action
    _db_execute(observation, result, st)
    return result


agent.telemetry = _DB_REPORT

# Midseason market candidate search; preserve baseline before step 240.
_MP_BEFORE_DYNAMIC = _mp_select
def _mp_select(obs,raw,standard,st,schema,key):
    standard=_MP_BEFORE_DYNAMIC(obs,raw,standard,st,schema,key)
    orders=[list(o) for o in standard.get('market',[])];t=int(obs['step']);me=int(obs['player'])
    if t<240:return standard
    if t>=696 or not any(_at_vector(raw.get('market',[]))):return standard
    if any(o and o[0]=='BUY_LAND' for o in orders):return standard
    proj=projected_shed(raw,FarmView(obs));stock=int(proj.get('FERTILIZER',0))
    othergoods=sum(max(0,int(o[2])) for o in orders if len(o)>=3 and o[0] in ('BUY_PRODUCT','BUY_ANIMAL') and o[1]!='FERTILIZER')
    space=100-sum(proj.values())-othergoods;params=_at_params(obs);inv=int(obs['market']['inventory']['FERTILIZER']);cache={}
    v0=_at_vector(orders);solo=_at_sim(v0,[0]*10,inv,stock,space,params,cache)
    if solo is None or obs['market']['prices']['FERTILIZER']<=1:return standard
    target=solo[2];net=target-stock
    # Keep every non-fertilizer slot fixed. Empty appended slots have no other owner.
    allowed=[j for j,o in enumerate(orders) if not o or o[0] in ('HIRE','BUY_SEED') or (len(o)>=3 and o[1]=='FERTILIZER' and o[0] in ('BUY_PRODUCT','SELL'))]
    allowed+=list(range(len(orders),min(10,len(orders)+2)))
    allowed=sorted(set(allowed))
    fixed=[list(orders[j]) for j in allowed if j<len(orders) and orders[j] and orders[j][0] in ('HIRE','BUY_SEED')]
    if len(allowed)<len(fixed)+2:return standard
    chosen_slots=sorted(set(allowed[:3]+allowed[-3:]+[j for j,x in enumerate(v0) if x]))
    vectors=[('baseline',v0)];seen={tuple(v0)}
    def add(name,v):
        k=tuple(v)
        if k not in seen:seen.add(k);vectors.append((name,v))
    for j in chosen_slots:
        v=[0]*10;v[j]=net;add('net',v)
    pairs=[(a,b) for a in chosen_slots for b in chosen_slots if a<b]
    room=max(0,min(64,space-max(net,0)))
    for a,b in pairs:
        if a>=b or a not in allowed or b not in allowed:continue
        for e in sorted({8,24,room}):
            if not 0<e<=room:continue
            v=[0]*10;v[a]=max(0,net)+e;v[b]=net-v[a];add('buy_close',v)
        if stock:
            v=[0]*10;v[a]=-stock;v[b]=target;add('sell_cover',v)
    model=st['models'].get(key,{'w':[0.]*len(_MP_FAMILIES),'n':0,'ratio':1.})
    lm=max(model['w']);weights=[math.exp(w-lm) for w in model['w']];s=sum(weights)
    conf=min(.9,model['n']/(model['n']+2.));weights=[.9*(conf*w/s+(1-conf)/len(weights)) for w in weights]
    expected=max(-64,min(64,round(net*model['ratio'])))
    scenarios=[(_mp_hyp(f,schema,expected),w) for f,w in zip(_MP_FAMILIES,weights)]
    scenarios += [([0]*10,.05),(_mp_hyp('native',schema,max(-96,min(96,expected*2))),.05)]
    refs=[_at_sim(v0,y,inv,stock,space,params,cache) for y,w in scenarios]
    if any(r is None or r[2]!=target for r in refs):return standard
    farm=obs['farms'][me];othercost=0;hires=int(farm['hires_today'])
    for o in orders:
        if not o:continue
        if o[0]=='HIRE':othercost+=_v219_fib(hires);hires+=1
        elif len(o)>=3 and o[0]=='BUY_SEED':othercost+=int(o[2])*{'WHEAT':10,'CARROT':20,'TOMATO':50,'STRAWBERRY':100,'MELON':80}[o[1]]
        elif len(o)>=3 and o[0]=='BUY_ANIMAL':othercost+=int(o[2])*{'COW':400,'SHEEP':500,'GOOSE':300}[o[1]]
        elif len(o)>=3 and o[0]=='BUY_PRODUCT' and o[1]!='FERTILIZER':othercost+=int(o[2])*(int(obs['market']['prices'][o[1]])+50)
    best=(0.,'baseline',v0)
    for name,v in vectors[1:]:
        if sum(bool(v[j]) for j in allowed)+len(fixed)>len(allowed):continue
        gs=[];own=[];ok=True
        for (y,w),ref in zip(scenarios,refs):
            r=_at_sim(v,y,inv,stock,space,params,cache)
            if r is None or r[2]!=target or r[3]!=ref[3] or r[4]+othercost+3000>farm['money']:
                ok=False;break
            gs.append((r[0]-ref[0])-(r[1]-ref[1]));own.append(r[0]-ref[0])
        if not ok:continue
        mean=sum(w*g for (_,w),g in zip(scenarios,gs));ownmean=sum(w*g for (_,w),g in zip(scenarios,own))
        score=.8*mean+.2*min(gs)
        if score>best[0]+1 and ownmean>=0:best=(score,name,v)
    _MP_REPORT['evaluations']+=1
    if best[1]=='baseline':return standard
    for _ in range(max(len(orders),max(allowed)+1)-len(orders)):orders.append([])
    vacant=[j for j in allowed if not best[2][j]]
    placements=dict(zip(vacant,fixed))
    for j in allowed:
        if j>=len(orders):continue
        q=best[2][j];orders[j]=['BUY_PRODUCT' if q>0 else 'SELL','FERTILIZER',abs(q)] if q else placements.get(j,[])
    result=dict(standard,market=orders);_MP_REPORT['changes']+=1
    assert [o for o in orders if o and o[0] in ('HIRE','BUY_SEED')]==[o for o in standard['market'] if o and o[0] in ('HIRE','BUY_SEED')]
    _db_log('market_reschedule',step=t,score=round(best[0],3),fixed_orders=len(fixed))
    if len(_MP_REPORT['records'])<150:_MP_REPORT['records'].append({'step':t,'kind':best[1],'score':round(best[0],3),'context':key,'samples':model['n'],'before':v0,'after':best[2]})
    return result

_MARKET_WIDE_PARENT=agent
del agent

def agent(observation,configuration=None):
    return _MARKET_WIDE_PARENT(observation,configuration)

agent.telemetry=_DB_REPORT



DB_MAX_SITES = 0
DB_MIN_GAIN = 0
DB_START = 192

"""Market-conditioned species choice for an existing second-field batch.

The parent retains ownership of the farm's routes, feed, harvest and sales.
This layer changes one already funded pasture contract from sheep to cow when
two existing smoothie shops support milk demand. It confirms the purchase and
pickup from observed inventory before changing the subsequent PLACE action.
"""
_SC_PARENT = agent
del agent
_SC_STATE = {}
_SC_REPORT = {'proposed': 0, 'bought': 0, 'picked': 0, 'placed': 0,
              'aborted': 0, 'events': []}


def _sc_stock(obs, item):
    private = obs['private']
    return int(private['shed'].get(item, 0)) + sum(
        int(bag.get(item, 0)) for bag in private['inventories'])


def _sc_plan(obs, action):
    step = int(obs['step'])
    if not 180 <= step <= 200:
        return None
    shops = list(obs.get('town', {}).get('unlocked_shops', []))
    if shops[:2] != ['SMOOTHIE_SHOP', 'SMOOTHIE_SHOP']:
        return None
    if _UP_CFG['species_guard'] and not _up_species_ok(obs, action):
        return None
    seat = int(obs['player'])
    state = _IMPL.chassis.players.get(seat)
    if not state or state.get('route') != 107:
        return None
    order = next((i for i, row in enumerate(action.get('market', []))
                  if row and row[:2] == ['BUY_ANIMAL', 'SHEEP']
                  and len(row) >= 3 and row[2] >= 2), None)
    if order is None or len(action['market']) >= 10:
        return None
    farm = obs['farms'][seat]
    visits = _db_visits(obs, action)
    choices = []
    for pos, path in visits.items():
        if not (pos[0] >= 5 and pos[1] < 5):
            continue
        for t, actor, op in path:
            if op != 'PLACE' or not step < t <= step + 24:
                continue
            command = _ca_tape(seat, t)
            units = [command.get('farmer') or ['PASS']] + list(command.get('hands') or [])
            if actor >= len(units) or units[actor][:2] != ['PLACE', 'SHEEP']:
                continue
            pickups = [(u, j) for p, route in visits.items()
                       for u, j, op2 in route
                       if step < u < t and j == actor and op2 == 'PICKUP'
                       and p in ((4, 4), (5, 4), (4, 5), (5, 5))]
            pickups = [(u, j) for u, j in pickups
                       if ([(_ca_tape(seat, u).get('farmer') or ['PASS'])] +
                            list(_ca_tape(seat, u).get('hands') or []))[j][:2]
                       == ['PICKUP', 'SHEEP']]
            if pickups:
                choices.append((t, actor, pos, max(pickups)[0]))
    if len(choices) < 2:
        return None
    # The later placement starts producing later, reducing the downside if
    # later shop draws do not sustain the observed milk demand.
    place_step, actor, pos, pickup_step = max(choices)
    return dict(order=order, actor=actor, pos=pos, pickup_step=pickup_step,
                place_step=place_step, bought=step,
                pre_cow=_sc_stock(obs, 'COW'), status='requested')


def _sc_reconcile(obs, plan):
    step = int(obs['step'])
    if plan['status'] == 'requested' and step > plan['bought']:
        if _sc_stock(obs, 'COW') <= plan['pre_cow']:
            plan['status'] = 'aborted'
        else:
            plan['status'] = 'bought'
            _SC_REPORT['bought'] += 1
    if plan['status'] == 'pickup_sent' and step > plan['pickup_step']:
        bag = obs['private']['inventories']
        if plan['actor'] >= len(bag) or bag[plan['actor']].get('COW', 0) < 1:
            plan['status'] = 'aborted'
        else:
            plan['status'] = 'picked'
            _SC_REPORT['picked'] += 1
    if plan['status'] == 'place_sent' and step > plan['place_step']:
        pos = plan['pos']; farm = obs['farms'][int(obs['player'])]
        tile = farm['tiles'][pos[1]][pos[0]]
        if isinstance(tile, dict) and tile.get('animal') == 'COW':
            plan['status'] = 'placed'
            _SC_REPORT['placed'] += 1
        else:
            plan['status'] = 'aborted'
    if plan['status'] == 'aborted' and not plan.get('counted'):
        plan['counted'] = True
        _SC_REPORT['aborted'] += 1


# Farm2945 execution and market upgrade. Original implementation, September 2026.
# Order compaction / commodity-before-fixed-orders and the temporary wheat
# opening are mechanisms studied in the uploaded Apache-2.0 Harvest Ledger.
# Preserve upstream authors, LICENSE.txt and NOTICE.txt when distributing.
_UP_CFG = dict(queue=True, wheat_first=True, seed_cap=True, opening=False,
               simultaneous=True, feed_calendar=True, species_guard=True,
               repair=True)
_UP_STATE = {}
_UP_REPORT = dict(queue=0, wheat_first=0, seed_cut=0, repair=0,
                  opening=0, errors=[], feed_pass=0, species_keep=0)


def _up_state(obs):
    p=int(obs['player']);t=int(obs['step']);st=_UP_STATE.get(p)
    if st is None or t<st['step'] or t==0 and st['step']!=0:
        st=_UP_STATE[p]={'step':t,'build':{},'open':False}
        if t==0:
            for k in _UP_REPORT:_UP_REPORT[k]=[] if k=='errors' else 0
    st['step']=t
    return st


def _up_project(obs,action):
    f,pr=_PLANNER_NS['_clone_state'](obs['farms'][int(obs['player'])],obs['private'])
    cmds=[action.get('farmer') or ['PASS']]+list(action.get('hands') or [])
    counts={}
    for c in cmds:
        if c and c[0]=='PLANT':counts[c[1]]=counts.get(c[1],0)+1
    blocked={x for x,q in counts.items() if q>pr['seeds'].get(x,0)}
    for i,c in enumerate(cmds[:len(pr['inventories'])]):
        if c and c[0]=='PLANT' and c[1] in blocked:c=['PASS']
        _PLANNER_NS['_apply_unit_action'](f,pr,i,c or ['PASS'],10,int(obs['step'])//24,24,100)
    return f,pr


def _up_begin(obs):
    st=_up_state(obs)
    if int(obs['step'])!=0 or not _UP_CFG['opening']:return
    tape=_IMPL.chassis.routes[0]
    # This documented one-tile project occupies only previously idle slots and
    # restores the pasture before the original cow pickup/deployment.
    edits={(2,1):['WEST'],(3,1):['WEST'],(4,1):['WEST'],
           (5,1):['PLANT','WHEAT'],(6,1):['WATER'],
           (49,0):['WEST'],(50,0):['WEST'],(51,0):['WEST'],(52,0):['WATER'],
           (84,0):['EAST'],(85,0):['EAST'],(86,0):['WATER'],
           (87,0):['HARVEST'],(88,0):['BUILD_PASTURE'],
           (89,0):['EAST'],(90,0):['EAST'],(91,0):['DROP']}
    # Do not silently install a foreign route on incompatible code.
    if not all(tape[t]['hands'][i] in (['PASS'],v) for (t,i),v in edits.items()):return
    for (t,i),v in edits.items():tape[t]['hands'][i]=v[:]
    tape[29]['hands'][2]=['WATER']
    if ['BUY_SEED','WHEAT',1] not in tape[2]['market']:
        tape[2]['market'].append(['BUY_SEED','WHEAT',1])
    st['open']=True;_UP_REPORT['opening']+=1


def _up_feed_safe(obs,action):
    """Conservative temporal food test; only existing wheat stocks get credit.

    No growth from unplanted crops, no future purchases, no hidden stock.
    Credits arrive after an observed crop's planned harvest and warehouse visit,
    not merely because the crop will be ripe. Native FEED requests are an upper
    bound on actual feeding; all existing commitments remain in that bound.
    """
    p=int(obs['player']);t=int(obs['step']);end=min(719,t+48)
    stock=_ca_wheat_total(obs);need=_ca_feed_need(p,t,_CA_FEED_DAYS)
    if stock>=need:return True
    if not _UP_CFG['feed_calendar']:return False
    f=obs['farms'][p];positions=[tuple(f['farmer'])]+list(map(tuple,f['hands']))
    wheat={}
    for y,row in enumerate(f['tiles']):
        for x,tile in enumerate(row):
            if isinstance(tile,dict) and tile.get('crop')=='WHEAT' and tile.get('yield_units',0)>0:
                wheat[x,y]=dict(tile)
    pending={};available=float(stock);initial=float(stock)
    for s in range(t,end+1):
        a=action if s==t else _ca_tape(p,s)
        units=[a.get('farmer') or ['PASS']]+list(a.get('hands') or [])
        for i,cmd in enumerate(units[:len(positions)]):
            pos=positions[i];op=cmd[0] if cmd else 'PASS'
            if op=='FEED':
                available-=1
                if available<0:return False
            if op=='HARVEST' and pos in wheat:
                z=wheat.pop(pos);age=s//24-int(z['planted_day'])
                if age>=2:
                    y=int(z['yield_units']);mls=int(z.get('max_lifespan_step',-1))
                    if mls>=0:y=max(0,y-_ca_decays(mls,t,s))
                    pending[i]=pending.get(i,0)+y
            elif op in ('PLANT','DIG','BUILD_PASTURE','BUILD_COOP'):
                wheat.pop(pos,None)
            if op in ('DROP','PLACE') and pos in ((4,4),(4,5),(5,4),(5,5)):
                if op=='DROP' or len(cmd)>1 and cmd[1]=='WHEAT':
                    q=pending.get(i,0)
                    if op=='PLACE' and len(cmd)>2:q=min(q,max(0,int(cmd[2])))
                    available+=q;pending[i]=pending.get(i,0)-q
            if op in _CA_MOVES:
                dx,dy=_CA_MOVES[op];positions[i]=(max(0,min(9,pos[0]+dx)),max(0,min(9,pos[1]+dy)))
        for o in a.get('market',[]):
            if o and o[0]=='HIRE':positions.append(tuple(_ca_spawn([list(x) for x in positions],10)))
        if s%24==23:
            # Do not credit overnight delivery when the current global stock
            # plus promised harvest could exceed capacity.
            allstock=sum(obs['private']['shed'].values())+sum(sum(b.values()) for b in obs['private']['inventories'])
            if allstock+sum(pending.values())<=100:available+=sum(pending.values())
            pending={};positions=[(4,4)]
    _UP_REPORT['feed_pass']+=1
    return True


def _up_species_ok(obs,action):
    # Replace the old two-shop hard rule by a diversification gate. The farm's
    # original HERD2/COWSWAP keep doing their full decisions. This optional extra
    # sheep->cow conversion is not allowed to further concentrate an already
    # milk-heavy herd before future demand is known.
    f=obs['farms'][int(obs['player'])]
    counts={'COW':0,'SHEEP':0,'GOOSE':0}
    for row in f['tiles']:
        for tile in row:
            if isinstance(tile,dict) and tile.get('animal') in counts:counts[tile['animal']]+=1
    for it in counts:counts[it]+=_sc_stock(obs,it)
    for o in action.get('market',[]):
        if len(o)>=3 and o[0]=='BUY_ANIMAL':counts[o[1]]+=max(0,int(o[2]))
    ok=counts['COW']<=counts['SHEEP']
    if not ok:_UP_REPORT['species_keep']+=1
    return ok


# Adapted from the uploaded Harvest Ledger / credited tetsutani, Apache-2.0.
import itertools as _v44y_it
_V44Y_REPORT = dict(v44y_reorder_turns=0, v44y_reorder_gain=0.0, v44y_errors=0)
def _v44y_price(item, inventory, params):
    return _r37_market_price(item, inventory, params)


def _v44y_params(obs):
    params = {k: dict(v) for k, v in _R37_MARKET_PARAMS.items()}
    for k, patch in (obs['market'].get('params') or {}).items():
        if k in params and isinstance(patch, dict): params[k].update(patch)
    return params


def _v44y_lockstep(orders_me, orders_opp, inv0, stock_me, stock_opp, params):
    """Replay the engine's per-slot / per-unit lockstep for SELL and BUY_PRODUCT orders (money-unbounded).
    Returns (revenue_me, revenue_opp)."""
    inv = dict(inv0); stock = [dict(stock_me), dict(stock_opp)]; rev = [0.0, 0.0]
    queues = [list(orders_me), list(orders_opp)]
    for i in range(max(len(queues[0]), len(queues[1]))):
        rem = [None, None]
        for p in (0, 1):
            if i < len(queues[p]):
                o = queues[p][i]
                if o and len(o) >= 3 and o[0] in ('SELL', 'BUY_PRODUCT') and o[1] in params:
                    try: n = int(o[2])
                    except Exception: n = 0
                    if n > 0: rem[p] = [o[0], o[1], n]
        guard = 0
        while True:
            guard += 1
            if guard > 5000: break
            quoted = [None, None]
            for p in (0, 1):
                r = rem[p]
                if r is None or r[2] <= 0: continue
                if r[0] == 'SELL':
                    quoted[p] = ('SELL', r[1], _v44y_price(r[1], inv[r[1]], params))
                elif r[1] in ('WHEAT', 'FERTILIZER'):
                    quoted[p] = ('BUY_PRODUCT', r[1], _v44y_price(r[1], inv[r[1]] - 1, params))
                else:
                    rem[p] = None
            if quoted[0] is None and quoted[1] is None: break
            committed = False
            for p in (0, 1):
                q = quoted[p]
                if q is None: continue
                op, item, price = q
                if op == 'SELL':
                    if stock[p].get(item, 0) <= 0:
                        rem[p] = None; continue
                    stock[p][item] -= 1; rev[p] += price
                    if price > 1: inv[item] += 1
                else:
                    stock[p][item] = stock[p].get(item, 0) + 1; rev[p] -= price; inv[item] -= 1
                rem[p][2] -= 1; committed = True
            if not committed: break
    return rev[0], rev[1]


def _v44y_factor_margin(opp, inv0, stock, params):
    # EXP298: cache independent item schedules, preserving the donor's exact search/ties.
    # The donor model has no shared cash/capacity constraint; per-item revenues add.
    cache = {}
    opp_schedules = {}
    for i, order in enumerate(opp):
        if order and len(order) >= 3 and order[0] in ('SELL', 'BUY_PRODUCT') and order[1] in params:
            item = order[1]
            padded = opp_schedules.setdefault(item, [[] for _ in opp])
            padded[i] = order
    def margin(cand):
        schedules = {item: [] for item in opp_schedules}
        for i, order in enumerate(cand):
            if order and len(order) >= 3 and order[0] in ('SELL', 'BUY_PRODUCT') and order[1] in params:
                schedules.setdefault(order[1], []).append((i, order[0], int(order[2])))
        total = 0.0
        for item, schedule in schedules.items():
            key = (item, tuple(schedule))
            value = cache.get(key)
            if value is None:
                mine = [[] for _ in cand]
                for i, op, n in schedule: mine[i] = [op, item, n]
                theirs = opp_schedules.get(item, [[] for _ in opp])
                a, b = _v44y_lockstep(mine, theirs, {item: inv0[item]},
                                      {item: stock.get(item, 0)}, {item: stock.get(item, 0)},
                                      {item: params[item]})
                value = a - b
                cache[key] = value
            total += value
        return total
    return margin


def _v44y_reorder(obs, action):
    market = action.get('market') or []
    if len(market) < 2: return action
    orders = [list(o) if isinstance(o, (list, tuple)) else o for o in market]
    blocks = []; i = 0
    while i < len(orders):
        o = orders[i]
        if o and o[0] == 'SELL':
            j = i
            while j < len(orders) and orders[j] and orders[j][0] == 'SELL': j += 1
            if 2 <= j - i <= 6: blocks.append((i, j))
            i = j
        else: i += 1
    if not blocks: return action
    view = FarmView(obs)
    stock = projected_shed(action, view)
    stock = {k: max(0, int(v)) for k, v in stock.items()}
    params = _v44y_params(obs)
    inv0 = {k: int(v) for k, v in obs['market']['inventory'].items()}
    opp = [list(o) for o in orders]
    margin = _v44y_factor_margin(opp, inv0, stock, params)
    base = margin(orders); best = base; best_orders = None
    for (i, j) in blocks:
        blk = orders[i:j]; n = j - i
        seen = set()
        for perm in _v44y_it.permutations(range(n)):
            key = tuple((blk[p][1], int(blk[p][2])) for p in perm)
            if key in seen: continue
            seen.add(key)
            cand = orders[:i] + [blk[p] for p in perm] + orders[j:]
            v = margin(cand)
            if v > best + 0.5: best = v; best_orders = cand
        if best_orders is not None:
            orders = best_orders; best_orders = None
    if best <= base + 0.5: return action
    _V44Y_REPORT['v44y_reorder_turns'] += 1; _V44Y_REPORT['v44y_reorder_gain'] += best - base
    out = dict(action); out['market'] = orders
    return out



def _up_finish(obs,action):
    st=_up_state(obs);t=int(obs['step']);p=int(obs['player'])
    result=dict(action,farmer=list(action.get('farmer') or ['PASS']),
                hands=[list(c) for c in action.get('hands',[])],
                market=[list(o) for o in action.get('market',[])])
    cmds=[result['farmer']]+result['hands'];f=obs['farms'][p]
    positions=[tuple(f['farmer'])]+list(map(tuple,f['hands']))
    if _UP_CFG['repair']:
        # A BUILD that encounters a weed only clears it. Keep that exact
        # building contract until an observed matching structure exists.
        for xy,contract in list(st['build'].items()):
            tile=f['tiles'][xy[1]][xy[0]]
            if isinstance(tile,dict) and tile.get('kind')==contract['kind']:
                del st['build'][xy];continue
            if tile is not None and not (isinstance(tile,dict) and tile.get('kind')=='WEED'):
                continue
            if t>contract['until']:
                del st['build'][xy];continue
            for i,pos in enumerate(positions):
                if pos==xy and i<len(cmds) and cmds[i]==['PASS']:
                    cmds[i]=['BUILD_'+contract['kind']];_UP_REPORT['repair']+=1;break
        for i,c in enumerate(cmds[:len(positions)]):
            if c and c[0] in ('BUILD_PASTURE','BUILD_COOP'):
                xy=positions[i];tile=f['tiles'][xy[1]][xy[0]]
                if isinstance(tile,dict) and tile.get('kind')=='WEED':
                    st['build'][xy]={'kind':c[0][6:],'until':min(718,t+24)}
    # Guard the temporary crop's failed initial purchase: restore original
    # BUILD when there is no actual day-zero wheat on the target tile.
    if _UP_CFG['opening'] and st.get('open') and t==29 and len(cmds)>3:
        z=f['tiles'][4][2]
        if not isinstance(z,dict) or z.get('crop')!='WHEAT' or z.get('planted_day')!=0:
            if cmds[3]==['WATER']:cmds[3]=['BUILD_PASTURE']
    result['farmer']=cmds[0];result['hands']=cmds[1:]
    if _UP_CFG['opening'] and st.get('open') and t==91 and len(positions)>1 and positions[1]==(4,4) and cmds[1]==['DROP']:
        q=int(obs['private']['inventories'][1].get('WHEAT',0))
        if q and obs['market']['prices']['WHEAT']>=31 and len(result['market'])<10:
            result['market'].append(['SELL','WHEAT',q])
    result=_up_late_seedfloat(obs,result)
    orders=result['market']
    if _UP_CFG['seed_cap'] and t>=624 and any(len(o)>=3 and o[0]=='BUY_SEED' for o in orders):
        native=_IMPL.chassis.players.get(p);need=0
        if native:
            for s in range(t+1,min(672,719)):
                a=_IMPL.chassis.routes[2 if s>=648 else native['route']][s]
                need+=sum(c and len(c)>1 and c[0]=='PLANT' and c[1] in ('WHEAT','CARROT') for c in [a.get('farmer')]+list(a.get('hands') or []))
            # Include already queued retries; do not count future long crops.
            need+=sum(c and len(c)>1 and c[0]=='PLANT' and c[1] in ('WHEAT','CARROT') for q in native.get('pending',{}).values() for xy,c in q)
            available={it:max(0,int(obs['private']['seeds'].get(it,0))-sum(c[:2]==['PLANT',it] for c in cmds)) for it in ('WHEAT','CARROT')}
            for j,o in enumerate(orders):
                if len(o)>=3 and o[0]=='BUY_SEED' and o[1] in available:
                    it=o[1];q=min(int(o[2]),max(0,need-available[it]));available[it]+=q
                    cut=int(o[2])-q
                    _UP_REPORT['seed_cut']+=cut
                    if it=='CARROT' and p in _CA_STATE:_CA_STATE[p]['spare_carrot']=max(0,_CA_STATE[p].get('spare_carrot',0)-cut)
                    orders[j]=['BUY_SEED',it,q] if q else []
    if _UP_CFG['queue'] and t>=144 and len(orders)>1:
        _,private=_up_project(obs,result);remaining=dict(private['shed']);uncertain=set();out=[]
        # Fertilizer cycles are optimized jointly upstream. Do not change their
        # internal slot structure after its estimate was made.
        fertility_cycle=sum(len(o)>=3 and o[1]=='FERTILIZER' and o[0] in ('SELL','BUY_PRODUCT') for o in orders)>1
        if not fertility_cycle:
            for o in orders[:10]:
                if not o:continue
                if len(o)>=3 and int(o[2])<=0:continue
                if o[0]=='BUY_LAND' and len(f['unlocked_quadrants'])==4:continue
                if len(o)>=3:
                    op,it,q=o[:3]
                    if op=='SELL' and it not in uncertain:
                        n=min(max(0,int(q)),remaining.get(it,0));remaining[it]=remaining.get(it,0)-n
                        if n<=0:continue
                    elif op in ('BUY_PRODUCT','BUY_ANIMAL'):uncertain.add(it)
                out.append(o)
            if out!=orders:_UP_REPORT['queue']+=1;orders=out
            # Market-sensitive commodity purchases may outrank fixed-price
            # seeds/HIRE only if all of them can be paid without any sale.
            if _UP_CFG['wheat_first'] and _r97_budget(obs,orders) and (_HM_STATES.get(p,{}).get('active') or not any(len(o)>=3 and o[0]=='SELL' and o[1] not in ('WHEAT','FERTILIZER') and int(o[2])>0 for o in orders)):
                buys=[o for o in orders if len(o)>=3 and o[:2]==['BUY_PRODUCT','WHEAT']]
                if buys and not any(len(o)>1 and o[:2]==['SELL','WHEAT'] for o in orders):
                    new=buys+[o for o in orders if not(len(o)>=3 and o[:2]==['BUY_PRODUCT','WHEAT'])]
                    if new!=orders:orders=new;_UP_REPORT['wheat_first']+=1
    result['market']=orders
    if t>=216:
        result=_v44y_reorder(obs,result)
        orders=result['market']
    if result!=action:
        # No observer may learn from a stale upstream order list.
        mp=_MP_STATE.get(p)
        if mp:mp['receipt']=None;mp['sp_receipt']=None
        if p in _AT_STATE:_at_remember(obs,result,_AT_STATE[p])
        _rp_remember(obs,result)
    return result

