_HM_MARKET_SOURCE='def _refresh_prices(market):\n    params = market.get("params")\n    for item in PRODUCTS:\n        market["prices"][item] = market_price(item, market["inventory"][item], params)\n\ndef _spawn_hand(farm, board_size):\n    """First free shed-access tile (NWSE order); ties broken by min occupancy."""\n    occupants = {tile: 0 for tile in _shed_access_tiles(board_size)}\n    all_pos = [tuple(farm["farmer"])] + [tuple(p) for p in farm["hands"]]\n    for pos in all_pos:\n        if pos in occupants:\n            occupants[pos] += 1\n    best = sorted(occupants.items(), key=lambda kv: (kv[1], _shed_access_tiles(board_size).index(kv[0])))\n    return list(best[0][0])\n\ndef _process_market(state, env):\n    """Per-unit lockstep: at each step, quote both players\' current-unit prices, then commit both."""\n    obs0 = state[0].observation\n    market = obs0.market\n    farms = obs0.farms\n    privates = [s.observation.private for s in state]\n    board_size = int(get(env.configuration, "boardSize", 10))\n    max_orders = max(1, int(get(env.configuration, "maxMarketOrdersPerTurn", 10)))\n    hire_mult = int(get(env.configuration, "farmHandCostMult", FARM_HAND_COST_MULT))\n    shed_capacity = int(get(env.configuration, "shedCapacity", 100))\n\n    queues = []\n    for s in state:\n        action = s.action if isinstance(s.action, dict) else {}\n        m = action.get("market", []) if isinstance(action, dict) else []\n        q = list(m) if isinstance(m, list) else []\n        queues.append(q[:max_orders])\n\n    max_len = max((len(q) for q in queues), default=0)\n    for i in range(max_len):\n        order_states = []\n        for player_id, q in enumerate(queues):\n            ostate = None\n            if i < len(q):\n                ostate = _parse_order(q[i])\n            order_states.append(ostate)\n\n        # Atomic orders (HIRE, BUY_LAND): handle once, in player order.\n        for player_id, ostate in enumerate(order_states):\n            if ostate is None:\n                continue\n            op = ostate["type"]\n            if op == "HIRE":\n                _do_hire(farms[player_id], privates[player_id], board_size, hire_mult)\n                order_states[player_id] = None\n            elif op == "BUY_LAND":\n                _do_buy_land(farms[player_id], board_size)\n                order_states[player_id] = None\n\n        # Per-unit lockstep loop for SELL / BUY_*.\n        idx_esc = 0\n        while True:\n            idx_esc += 1\n            if idx_esc >= 100_000:\n                print("WARNING: kaggriculture market loop exceeded 100k iterations; aborting")\n                break\n            quoted = [None, None]\n            for player_id, ostate in enumerate(order_states):\n                if ostate is None or ostate["remaining"] <= 0:\n                    continue\n                op = ostate["type"]\n                item = ostate["item"]\n                if op == "SELL" and item in PRODUCTS:\n                    quoted[player_id] = ("SELL", item, market_price(item, market["inventory"][item], market.get("params")), ostate)\n                elif op == "BUY_PRODUCT" and item in ("WHEAT", "FERTILIZER"):\n                    # Quote at post-buy inventory so a buy/sell round-trip\n                    # against an unchanged market nets zero.\n                    quoted[player_id] = ("BUY_PRODUCT", item, market_price(item, market["inventory"][item] - 1, market.get("params")), ostate)\n                elif op == "BUY_SEED" and item in CROPS:\n                    quoted[player_id] = ("BUY_SEED", item, CROPS[item]["seed"], ostate)\n                elif op == "BUY_ANIMAL" and item in ANIMALS:\n                    quoted[player_id] = ("BUY_ANIMAL", item, ANIMALS[item]["cost"], ostate)\n                else:\n                    order_states[player_id] = None  # malformed sub-op; abort\n\n            if all(q is None for q in quoted):\n                break\n\n            # Both players see the same pre-commit inventory for this unit.\n            committed_any = False\n            for player_id, q in enumerate(quoted):\n                if q is None:\n                    continue\n                op, item, price, ostate = q\n                ok = _commit_unit(op, item, price, farms[player_id], privates[player_id], market, shed_capacity)\n                if ok:\n                    ostate["remaining"] -= 1\n                    committed_any = True\n                else:\n                    order_states[player_id] = None  # can\'t continue this order\n\n            if not committed_any:\n                break\n\n        _refresh_prices(market)\n\ndef _parse_order(order):\n    if not isinstance(order, list) or not order:\n        return None\n    op = order[0]\n    if op == "HIRE":\n        return {"type": "HIRE"}\n    if op == "BUY_LAND":\n        return {"type": "BUY_LAND"}\n    if op in ("BUY_SEED", "BUY_PRODUCT", "BUY_ANIMAL", "SELL"):\n        if len(order) < 3:\n            return None\n        try:\n            n = int(order[2])\n        except (TypeError, ValueError):\n            return None\n        if n <= 0:\n            return None\n        return {"type": op, "item": order[1], "remaining": n}\n    return None\n\ndef _commit_unit(op, item, price, farm, private, market, shed_capacity=100):\n    if op == "SELL":\n        if private["shed"].get(item, 0) <= 0:\n            return False\n        private["shed"][item] -= 1\n        farm["money"] += price\n        # Sales at $1 do not increase market supply.\n        if price > 1:\n            market["inventory"][item] += 1\n        return True\n    if op == "BUY_PRODUCT":\n        if farm["money"] < price:\n            return False\n        # Bought goods land in the shed, which obeys shedCapacity like every\n        # other deposit path (pickup, shed-drop, end-of-day drop).\n        if sum(private["shed"].values()) >= shed_capacity:\n            return False\n        farm["money"] -= price\n        private["shed"][item] = private["shed"].get(item, 0) + 1\n        market["inventory"][item] -= 1\n        return True\n    if op == "BUY_SEED":\n        if farm["money"] < price:\n            return False\n        farm["money"] -= price\n        private["seeds"][item] = private["seeds"].get(item, 0) + 1\n        return True\n    if op == "BUY_ANIMAL":\n        if farm["money"] < price:\n            return False\n        if sum(private["shed"].values()) >= shed_capacity:\n            return False\n        farm["money"] -= price\n        private["shed"][item] = private["shed"].get(item, 0) + 1\n        return True\n    return False\n\ndef _fib(n):\n    """Indexed so _fib(0)=1, _fib(1)=1, _fib(2)=2, _fib(3)=3, _fib(4)=5..."""\n    a, b = 1, 1\n    for _ in range(n):\n        a, b = b, a + b\n    return a\n\ndef _hire_cost(n_already_today, mult=FARM_HAND_COST_MULT):\n    return mult * _fib(n_already_today)\n\ndef _do_hire(farm, private, board_size, mult=FARM_HAND_COST_MULT):\n    cost = _hire_cost(farm["hires_today"], mult)\n    if farm["money"] < cost:\n        return\n    farm["money"] -= cost\n    farm["hires_today"] += 1\n    farm["hands"].append(_spawn_hand(farm, board_size))\n    private["inventories"].append({})\n\ndef _do_buy_land(farm, board_size):\n    n_unlocked_extra = len(farm["unlocked_quadrants"]) - 1  # NW is always there\n    if n_unlocked_extra >= len(LAND_ORDER):\n        return\n    cost = LAND_PRICES[n_unlocked_extra]\n    if farm["money"] < cost:\n        return\n    farm["money"] -= cost\n    quadrant = LAND_ORDER[n_unlocked_extra]\n    farm["unlocked_quadrants"].append(quadrant)\n    for y in range(board_size):\n        for x in range(board_size):\n            if _quadrant_of(x, y, board_size) == quadrant and farm["tiles"][y][x] == "LOCKED":\n                farm["tiles"][y][x] = None\n\ndef _decay_plants(farm, step):\n    board_size = len(farm["tiles"])\n    for y in range(board_size):\n        for x in range(board_size):\n            tile = farm["tiles"][y][x]\n            if not isinstance(tile, dict) or tile.get("kind") != "PLANT":\n                continue\n            mls = tile["max_lifespan_step"]\n            if mls < 0 or step < mls:\n                continue\n            if (step - mls) % 2 != 0:\n                continue\n            tile["yield_units"] -= 1\n            if tile["yield_units"] <= 0:\n                farm["tiles"][y][x] = {"kind": "WEED"}\n\ndef _daily_refresh_plants(farm, current_day, turns_per_day):\n    board_size = len(farm["tiles"])\n    next_day = current_day + 1\n    for y in range(board_size):\n        for x in range(board_size):\n            tile = farm["tiles"][y][x]\n            if not isinstance(tile, dict) or tile.get("kind") != "PLANT":\n                continue\n            was_watered = tile["watered_today"]\n            if was_watered:\n                tile["consecutive_unwatered"] = 0\n            else:\n                tile["consecutive_unwatered"] += 1\n            tile["watered_today"] = False\n            if tile["consecutive_unwatered"] >= 2:\n                farm["tiles"][y][x] = {"kind": "WEED"}\n                continue\n            cd = CROPS[tile["crop"]]\n            if not cd["ongoing"]:\n                continue\n            days_since_first = next_day - tile["planted_day"] - cd["first_yield_day"]\n            if days_since_first < 0:\n                continue\n            interval = cd["interval"]\n            if days_since_first % interval != 0:\n                continue\n            production_count = days_since_first // interval + 1\n            if production_count > cd["max_yield"]:\n                continue\n            # Fertilizer bonus only applies on watered days (basic needs first).\n            fertilized = was_watered and tile.get("fertilized_until_day", -1) >= current_day\n            tile["yield_units"] = min(cd["max_yield"], tile["yield_units"] + (2 if fertilized else 1))\n            if production_count == cd["max_yield"]:\n                tile["max_lifespan_step"] = (next_day + 1) * turns_per_day\n\ndef _daily_refresh_animals(farm, day):\n    board_size = len(farm["tiles"])\n    next_day = day + 1\n    for y in range(board_size):\n        for x in range(board_size):\n            tile = farm["tiles"][y][x]\n            if not (isinstance(tile, dict) and "animal" in tile):\n                continue\n            if tile["fed_today"]:\n                tile["consecutive_unfed"] = 0\n            else:\n                tile["consecutive_unfed"] += 1\n            if tile["consecutive_unfed"] >= 2:\n                # Animal escapes; structure remains.\n                farm["tiles"][y][x] = {"kind": ANIMALS[tile["animal"]]["structure"]}\n                continue\n            a = ANIMALS[tile["animal"]]\n            days_since_first = next_day - tile["placed_day"] - a["first_yield_day"]\n            if days_since_first >= 0 and days_since_first % a["interval"] == 0:\n                base = 1\n                # Care bonus only consumed on a fed production day.\n                bonus = tile.pop("pending_care_bonus", 0) if tile["fed_today"] else 0\n                tile["yield_units"] = min(a["max_held"], tile["yield_units"] + base + bonus)\n                tile["pending_care_bonus"] = 0\n            if tile["cared_today"] and tile["fed_today"]:\n                tile["pending_care_bonus"] = tile.get("pending_care_bonus", 0) + 1\n            tile["fertilizer_available"] = True\n            tile["fed_today"] = False\n            tile["cared_today"] = False\n\ndef _drop_inventories_to_shed(private, capacity):\n    """Drop every per-farmer inventory into the shed up to `capacity`; overflow is discarded.\n    Seeds are tracked separately in private["seeds"] and don\'t pass through the shed."""\n    shed = private["shed"]\n    for inv in private["inventories"]:\n        for item, n in list(inv.items()):\n            if n <= 0:\n                del inv[item]\n                continue\n            current = sum(v for k, v in shed.items())\n            room = max(0, capacity - current)\n            take = min(n, room)\n            if take > 0:\n                shed[item] = shed.get(item, 0) + take\n            del inv[item]'
_HM_STATES={}
_HM_REPORT={}

def _hm_prices(item,inventory,params=None):
    cache=_HM_ENGINE['_price_cache'];k=(item,int(inventory))
    if k not in cache:cache[k]=_r37_market_price(item,int(inventory),_HM_ENGINE['_price_params'])
    return cache[k]

_HM_ENGINE=dict(_PLANNER_NS)
_HM_ENGINE.update(PRODUCTS=list(PRODUCTS),FARM_HAND_COST_MULT=1,
    LAND_ORDER=['NE','SW','SE'],LAND_PRICES=[1000,2000,4000],
    get=lambda x,k,d=None:x.get(k,d) if isinstance(x,dict) else getattr(x,k,d),
    _quadrant_of=lambda x,y,n:('N' if y<n//2 else 'S')+('W' if x<n//2 else 'E'),
    market_price=_hm_prices,_price_cache={},_price_params={})
exec(_HM_MARKET_SOURCE,_HM_ENGINE)

def _hm_clean(v):
    if isinstance(v,dict):return {k:_hm_clean(x) for k,x in v.items() if x!=0 or isinstance(x,bool)}
    if isinstance(v,list):return [_hm_clean(x) for x in v]
    return v


def _hm_field_snapshot(obs,action,st):
    p=int(obs['player']);farms=copy.deepcopy(obs['farms']);priv=[None,None]
    priv[p]=copy.deepcopy(obs['private']);priv[1-p]=copy.deepcopy(st['private'])
    actions=[None,None];actions[p]=action;actions[1-p]=st['predicted']
    day=int(obs['step'])//24
    for seat in (0,1):
        cmds=[actions[seat].get('farmer') or ['PASS']]+list(actions[seat].get('hands') or [])
        need={}
        for cmd in cmds:
            if len(cmd)>1 and cmd[0]=='PLANT':need[cmd[1]]=need.get(cmd[1],0)+1
        blocked={k for k,q in need.items() if q>priv[seat]['seeds'].get(k,0)}
        for i,cmd in enumerate(cmds[:len(priv[seat]['inventories'])]):
            if len(cmd)>1 and cmd[0]=='PLANT' and cmd[1] in blocked:continue
            _HM_ENGINE['_apply_unit_action'](farms[seat],priv[seat],i,cmd,10,day,24,100)
    return farms,priv,actions

def _hm_settle(obs,snapshot,orders,st):
    farms0,priv0,actions0=snapshot;p=int(obs['player'])
    farms=[dict(f,farmer=list(f['farmer']),hands=[list(x) for x in f['hands']],
           tiles=[list(r) for r in f['tiles']],unlocked_quadrants=list(f['unlocked_quadrants'])) for f in farms0]
    priv=[dict(pr,shed=dict(pr['shed']),seeds=dict(pr['seeds']),inventories=[dict(i) for i in pr['inventories']]) for pr in priv0]
    market=dict(obs['market'],inventory=dict(obs['market']['inventory']),prices=dict(obs['market']['prices']))
    actions=[dict(x) for x in actions0];actions[p]['market']=orders
    states=[_HM_NS(observation=_HM_NS(farms=farms,private=priv[i],market=market),action=actions[i]) for i in (0,1)]
    _HM_ENGINE['_process_market'](states,_HM_NS(configuration=st['cfg']))
    value=float(farms[p]['money'])-float(farms[1-p]['money'])
    return value,farms,priv,market

def _hm_own_contract(result,reference,p):
    _,f,pr,_=result;_,rf,rpr,_=reference
    # Order optimization must not steal materials, seeds, staff or land from
    # the entire already-compiled Farm2945 production decision.
    return (f[p]['hands']==rf[p]['hands'] and f[p]['unlocked_quadrants']==rf[p]['unlocked_quadrants']
            and f[p]['hires_today']==rf[p]['hires_today'] and _hm_clean(pr[p])==_hm_clean(rpr[p]))

def _hm_optimize(obs,action,snapshot,reference,st):
    return action,reference



# Exact one-round responses to a verified PUBLIC strategy model. No hidden
# opponent fields are supplied by the real environment; the model's own
# estimate is used, with next-observation public-account validation.
_HM_OPTIMIZE=True
_HM_RESPONSE_BUDGET=.16

def _hm_dominates(result,reference,p):
    score,f,pr,m=result;old,rf,rpr,rm=reference
    if score<=old+.5 or f[p]['money']<rf[p]['money'] or f[1-p]['money']>rf[1-p]['money']:return False
    if m['inventory']!=rm['inventory']:return False
    for q in (0,1):
        if not _hm_own_contract(result,reference,q):return False
    return True

def _hm_input_factor(item,orders,rival,stock,enemy,inventory):
    """Fast candidate ranking only. Exact multi-good settlement certifies
    final candidates including cash, all staff, capacity and seed purchases."""
    cash=[0,0];have=[int(stock),int(enemy)];inv=int(inventory)
    for j in range(max(len(orders),len(rival))):
        ops=[]
        for os in (orders,rival):
            o=os[j] if j<len(os) else []
            ops.append([o[0],min(100,max(0,int(o[2])))] if len(o)>2 and o[1]==item and o[0] in ('SELL','BUY_PRODUCT') else ['',0])
        while any(q for _,q in ops):
            prices=[_hm_prices(item,inv-(op=='BUY_PRODUCT')) if n else 0 for op,n in ops]
            for q,(op,n) in enumerate(ops):
                if not n:continue
                if op=='SELL' and have[q]>0:
                    cash[q]+=prices[q];have[q]-=1;ops[q][1]-=1
                    if prices[q]>1:inv+=1
                elif op=='BUY_PRODUCT' and have[q]<100:
                    cash[q]-=prices[q];have[q]+=1;inv-=1;ops[q][1]-=1
                else:ops[q][1]=0
    return cash[0]-cash[1]

def _hm_optimize(obs,action,snapshot,reference,st):
    t=int(obs['step']);p=int(obs['player']);start=_hm_time.perf_counter();end=start+_HM_RESPONSE_BUDGET
    original=[list(o) for o in (action.get('market') or [])[:10]]
    best=[list(o) for o in original];best_result=reference;tested=set();n_eval=0
    def try_orders(orders):
        nonlocal best,best_result,n_eval
        if _hm_time.perf_counter()>=end:return False
        key=tuple(tuple(o) for o in orders)
        if key in tested:return False
        tested.add(key);r=_hm_settle(obs,snapshot,orders,st);n_eval+=1
        if r[0]>best_result[0]+.5 and _hm_dominates(r,reference,p):best=[list(o) for o in orders];best_result=r;return True
        return False
    rival=st['predicted'].get('market') or []
    # All current orders may compete for slots. Their execution products,
    # employees, land and both physical states must pass exact certification.
    if t>=st.get('response_start',144) and len(best)>=2:
        current=[list(o) for o in best]
        for i in range(len(current)):
            for j in range(i+1,len(current)):
                a,b=current[i],current[j]
                if not a or not b or a==b:continue
                if a[0] not in ('SELL','BUY_PRODUCT') and b[0] not in ('SELL','BUY_PRODUCT'):continue
                c=[list(o) for o in current];c[i],c[j]=c[j],c[i];try_orders(c)
    # Extend closed inventory cycles to BOTH tradeable inputs. Earlier
    # versions considered fertilizer only and kept all other slot indices
    # fixed, missing many feasible responses to the actual rival schedule.
    for item in ('FERTILIZER','WHEAT'):
        relevant=[(j,o) for j,o in enumerate(rival) if len(o)>2 and o[1]==item and o[0] in ('SELL','BUY_PRODUCT')]
        if t<st.get('response_start',144) or not relevant or _hm_time.perf_counter()>=end-.015:continue
        others=[list(o) for o in best if o and not(len(o)>2 and o[1]==item and o[0] in ('SELL','BUY_PRODUCT'))]
        if len(others)>9:continue
        pre=snapshot[1][p]['shed'].get(item,0);enemy=snapshot[1][1-p]['shed'].get(item,0)
        target=reference[2][p]['shed'].get(item,0);net=target-pre
        room=max(0,100-sum(snapshot[1][p]['shed'].values()))
        in0=obs['market']['inventory'][item];ranking=[];seen=set()
        def offer(first,last=None):
            slots={first[0]:first[1]}
            if last is not None:slots[last[0]]=last[1]
            out=[];cursor=0
            for j in range(10):
                if j in slots:out.append(slots[j])
                elif cursor<len(others):out.append(others[cursor]);cursor+=1
                else:out.append([])
            if cursor<len(others):return
            key=tuple(tuple(o) for o in out)
            if key in seen:return
            seen.add(key)
            score=_hm_input_factor(item,out,rival,pre,enemy,in0)
            ranking.append((score,key))
        for i in range(10):
            offer((i,['BUY_PRODUCT' if net>0 else 'SELL',item,abs(net)] if net else []))
        if len(others)<=8:
            edges={0,9}
            for j,o in relevant:edges.update((max(0,j-1),j,min(9,j+1)))
            edges=sorted(edges)
            buy_sizes=sorted({8,16,32,64,room,max(0,int(net)),max(0,int(net))+32,int(pre)+int(net)})
            for ii,i in enumerate(edges):
                for j in edges[ii+1:]:
                    if _hm_time.perf_counter()>=end-.015:break
                    for buy in buy_sizes:
                        sell=buy-net
                        if 0<buy<=100 and 0<sell<=100:
                            offer((i,['BUY_PRODUCT',item,buy]),(j,['SELL',item,sell]))
                            if sell<=pre:offer((i,['SELL',item,sell]),(j,['BUY_PRODUCT',item,buy]))
        ranking.sort(reverse=True)
        for score,key in ranking[:12]:try_orders([list(o) for o in key])
    if best_result is reference:return action,reference
    _HM_REPORT['changes']+=1;_HM_REPORT['estimated_margin_gain']+=best_result[0]-reference[0]
    if len(_HM_REPORT['records'])<300:
        _HM_REPORT['records'].append(dict(step=t,before=original,after=best,
            own_cash_gain=best_result[1][p]['money']-reference[1][p]['money'],
            rival_cash_change=best_result[1][1-p]['money']-reference[1][1-p]['money'],
            relative_gain=best_result[0]-reference[0],tested=n_eval,
            verified_public_prefix=_HM_REPORT['verified_turns']))
    _HM_REPORT['max_response_seconds']=max(_HM_REPORT.get('max_response_seconds',0),_hm_time.perf_counter()-start)
    return dict(action,market=best),best_result


