def _hm_before(obs, configuration):
    p = int(obs['player']); t = int(obs['step']); opp = 1-p
    bank = _HM_BANK.get(p)
    if bank is None or t == 0:
        bank = {'models': {}, 'selected': None, 'step': -1}
        _HM_BANK[p] = bank
        _HM_STATES[p] = {'active': False, 'step': -1, 'predicted': None}
        _HM_REPORT.clear()
        _HM_REPORT.update(model_turns=0, verified_turns=0, changes=0,
            estimated_margin_gain=0.0, model_errors=0, disabled_reason=None,
            records=[], identified=None, model_validation={}, abstained=0)
        cfg = copy.deepcopy(configuration or {})
        standard = t == 0 and not cfg.get('marketParams', {})
        standard = standard and all(cfg.get(k,v)==v for k,v in (
            ('boardSize',10),('turnsPerDay',24),('shedCapacity',100),
            ('farmHandCostMult',1),('maxMarketOrdersPerTurn',10)))
        pr = obs['private']
        standard = standard and len(pr['inventories']) == 1 and not any(pr['inventories'][0].values())
        standard = standard and not any(pr['shed'].values()) and not any(pr['seeds'].values())
        if not standard:
            _HM_REPORT['disabled_reason'] = 'unsupported initialization'
            return
        if not _HM_ENABLED:
            _HM_REPORT['disabled_reason'] = 'disabled by configuration'
            return
        for label, payload in _HM_BANK_PAYLOADS.items():
            st = {'name':label, 'step':-1, 'active':True, 'cfg':copy.deepcopy(cfg),
                  'predicted':None, 'private':copy.deepcopy(pr), 'verified':0,
                  # Preserve the qualified Harvest behavior; early-response
                  # capability is introduced for the new reactive family.
                  'response_start':1 if label=='reactive_v7' else 144}
            try:
                model={'__name__':'licensed_public_opponent_'+label}
                source = _hm_zlib.decompress(_hm_b64.b85decode(payload)).decode('utf-8')
                exec(compile(source, '<licensed opponent '+label+'>', 'exec'), model)
                st['model']=model
            except Exception as exc:
                st['active']=False
                _HM_REPORT['model_errors']+=1
                st['failure']=repr(exc)
            bank['models'][label]=st
    if not _HM_ENABLED:return
    alive=[]
    for label,st in bank['models'].items():
        if not st['active']:continue
        try:
            if st['step']!=t-1:raise ValueError('nonconsecutive observations')
            expected=st.get('expected')
            if expected is not None:
                actual=obs['farms'][opp]
                checks=(abs(float(actual['money'])-expected['money'])<1e-6,
                    actual['farmer']==expected['farmer'],actual['hands']==expected['hands'],
                    actual.get('hires_today')==expected['hires_today'],
                    actual['unlocked_quadrants']==expected['quadrants'],
                    obs['market']['inventory']==expected['market'],
                    _hm_clean(obs['private'])==_hm_clean(expected['own_private']))
                if not all(checks):raise ValueError('public prediction mismatch:'+str(checks))
                st['verified']+=1
            predicted_obs=copy.deepcopy(obs)
            predicted_obs['player']=opp
            predicted_obs['private']=copy.deepcopy(st['private'])
            st['predicted']=st['model']['agent'](predicted_obs,copy.deepcopy(st['cfg']))
            st['step']=t
            alive.append(st)
        except Exception as exc:
            st['active']=False;st['predicted']=None
            st['failure']=str(exc);st['failure_step']=t
            _HM_REPORT['model_errors']+=int(not isinstance(exc,ValueError))
        _HM_REPORT['model_validation'][label]={
            'active':st['active'],'verified_turns':st['verified'],
            'failure':st.get('failure'),'failure_step':st.get('failure_step')}
    bank['selected']=alive[0]['name'] if len(alive)==1 and alive[0]['verified'] else None
    bank['step']=t
    if bank['selected'] is not None:
        st=alive[0]
        _HM_STATES[p]=st
        _HM_REPORT['identified']=bank['selected']
        _HM_REPORT['model_turns']=st['step']+1
        _HM_REPORT['verified_turns']=st['verified']
        _HM_REPORT['disabled_reason']=None
    else:
        _HM_STATES[p]={'active':False,'step':t,'predicted':None}
        _HM_REPORT['abstained']+=1
        _HM_REPORT['disabled_reason']='ambiguous public prefix' if alive else 'no matching public model'

def _hm_record_expected(obs, st, result):
    p=int(obs['player']);t=int(obs['step'])
    _,farms,priv,market=result
    cfg=st['cfg'];shops=obs['town']['unlocked_shops']
    for item in PRODUCTS:
        if t%int(cfg.get('townShopSellInterval',4))==0:
            market['inventory'][item]-=sum(2 if len(_OR2_SHOPS[s])==1 else 1
                for s in shops if item in _OR2_SHOPS[s])
        if t%int(cfg.get('townCenterSellInterval',24))==0 and item!='FERTILIZER':
            market['inventory'][item]-=1
    if t%24==23:
        for i in (0,1):
            _HM_ENGINE['_drop_inventories_to_shed'](priv[i],100)
            priv[i]['inventories']=[{}]
            farms[i]['farmer']=[4,4];farms[i]['hands']=[]
            farms[i]['hires_today']=0
    st['private']=priv[1-p]
    st['expected']={'money':farms[1-p]['money'],'farmer':farms[1-p]['farmer'],
        'hands':farms[1-p]['hands'],'hires_today':farms[1-p]['hires_today'],
        'quadrants':farms[1-p]['unlocked_quadrants'],
        'market':market['inventory'],'own_private':priv[p]}

def _hm_finish(obs,action):
    action=_gr_apply(obs,action)
    p=int(obs['player']);t=int(obs['step']);bank=_HM_BANK.get(p)
    if not _HM_ENABLED or not bank or bank['step']!=t:return action
    alive=[st for st in bank['models'].values() if st['active'] and st['step']==t]
    selected=bank['models'].get(bank['selected']) if bank['selected'] else None
    selected_result=None;original_result=None;original=action
    _HM_ENGINE['_price_params']=_at_params(obs);_HM_ENGINE['_price_cache']={}
    if selected is not None:
        try:
            snapshot=_hm_field_snapshot(obs,action,selected)
            original_result=_hm_settle(obs,snapshot,action.get('market') or [],selected)
            selected_result=original_result
            if _HM_OPTIMIZE and t>=selected['response_start']:
                action,selected_result=_hm_optimize(obs,action,snapshot,original_result,selected)
        except Exception as exc:
            selected['active']=False;selected['failure']=repr(exc)
            _HM_REPORT['model_errors']+=1;_HM_REPORT['disabled_reason']=repr(exc)
            action=original;selected_result=None
    for st in alive:
        if not st['active']:continue
        try:
            if st is selected and selected_result is not None:result=selected_result
            else:
                snapshot=_hm_field_snapshot(obs,action,st)
                result=_hm_settle(obs,snapshot,action.get('market') or [],st)
            _hm_record_expected(obs,st,result)
        except Exception as exc:
            st['active']=False;st['failure']=repr(exc)
            _HM_REPORT['model_errors']+=1
    if action is not original:
        mp=_MP_STATE.get(p)
        if mp:mp['receipt']=None;mp['sp_receipt']=None
        if p in _AT_STATE:_at_remember(obs,action,_AT_STATE[p])
        _rp_remember(obs,action)
    return action


# Farm2945 general close-loss response (2026-09-24).
# Modified locally: cash/input queue competition, imminent fertilizer delivery,
# and bounded recovery inventory at the rule-defined $1 floor.
# Original source, licenses and known-opponent controllers remain in place.
# Native-trip fertilizer protection. Look two field phases ahead rather than
# retaining a season-wide stock. Does not change farmer/worker commands.
_FG_REPORT={'holds':0,'held_units':0,'errors':0,'records':[]}
def _fg_guard(obs,action):
    t=int(obs['step']);p=int(obs['player'])
    if not 144<=t<694:return action
    orders=[list(o) for o in action.get('market',[])]
    if not any(len(o)>2 and o[:2]==['SELL','FERTILIZER'] and o[2]>0 for o in orders):return action
    # Leave verified-model trades untouched in this first generalization.
    if _HM_STATES.get(p,{}).get('active'):return action
    if not _r97_budget(obs,orders):return action
    f,pr=_up_project(obs,action);stock,buys,_=_r97_market_stock(pr['shed'],orders)
    final,loss=_r97_delivery(stock,pr,t%24==23)
    positions=[tuple(f['farmer'])]+[tuple(z) for z in f['hands']]
    access=((4,4),(5,4),(4,5),(5,5))
    for o in orders:
        if o and o[0]=='HIRE':positions.append(min(access,key=lambda xy:(positions.count(xy),access.index(xy))))
    if t%24==23:positions=[(4,4)]
    need=0
    for s in (t+1,t+2):
        a=_ca_tape(p,s);cs=[a.get('farmer') or ['PASS']]+list(a.get('hands') or [])
        for i,pos in enumerate(positions):
            c=cs[i] if i<len(cs) else ['PASS']
            if c[:2]==['PICKUP','FERTILIZER'] and pos in access:need+=max(0,int(c[2]) if len(c)>2 else 1)
            if c and c[0] in _CA_MOVES:
                dx,dy=_CA_MOVES[c[0]];positions[i]=(min(9,max(0,pos[0]+dx)),min(9,max(0,pos[1]+dy)))
        for o in a.get('market',[]):
            if o and o[0]=='HIRE':positions.append(min(access,key=lambda xy:(positions.count(xy),access.index(xy))))
        if s%24==23:break
    short=max(0,need-int(final.get('FERTILIZER',0)))
    if not short:return action
    old=copy.deepcopy(orders)
    def calc(oo):
        st,bb,ss=_r97_market_stock(pr['shed'],oo);en,ll=_r97_delivery(st,pr,t%24==23)
        return en,bb,ll,ss
    for j in range(len(orders)-1,-1,-1):
        o=orders[j]
        if len(o)<3 or o[:2]!=['SELL','FERTILIZER']:continue
        en,bb,ll,ss=calc(orders);short=max(0,need-en.get('FERTILIZER',0))
        if not short:break
        cut=min(short,ss.get(j,0));oldq=o[2];o[2]=max(0,ss.get(j,0)-cut)
        new,bb,ll,_=calc(orders)
        if any(bb.get(i,0)<v for i,v in buys.items()) or any(q>loss.get(it,0) for it,q in ll.items()):o[2]=oldq
    new,bb,ll,_=calc(orders);held=new.get('FERTILIZER',0)-final.get('FERTILIZER',0)
    if held<=0:return action
    _FG_REPORT['holds']+=1;_FG_REPORT['held_units']+=held
    if len(_FG_REPORT['records'])<100:_FG_REPORT['records'].append(dict(step=t,need=need,held=held,before=old,after=orders))
    return dict(action,market=orders)

# Mixed-order queue allocation. Public receipts update a small per-match
# distribution over ordering styles; no player name, seed or replay is read.
_QX_STATE={}
_QX_KINDS=('native','sell_first','buy_first','price','impact')
_QX_REPORT={'changes':0,'learned':0,'ambiguous':0,'errors':0,'records':[]}
_QX_ENABLED=True

def _qx_rows(orders):
    counts={}
    for o in orders:
        if len(o)>2 and o[0] in ('SELL','BUY_PRODUCT') and int(o[2])>0:
            counts[o[1]]=counts.get(o[1],0)+1
    # Do not tear apart upstream round trips, duplicate lots or their anchors.
    return [j for j,o in enumerate(orders) if len(o)>2 and o[0] in ('SELL','BUY_PRODUCT') and int(o[2])>0 and counts[o[1]]==1]

def _qx_templates(obs,orders,net=None):
    ix=_qx_rows(orders);prices=obs['market']['prices'];inv=obs['market']['inventory'];params=_at_params(obs)
    rows=[]
    for j in ix:
        o=orders[j][:]
        if net is not None:
            q=net.get(o[1],0)
            if q==0:o=[]
            else:o=['SELL' if q>0 else 'BUY_PRODUCT',o[1],abs(int(q))]
        rows.append(o)
    def rank(o,kind):
        if not o:return (2,0)
        op,it,n=o
        if kind=='sell_first':return (op!='SELL',0)
        if kind=='buy_first':return (op!='BUY_PRODUCT',0)
        if kind=='price':return (op!='SELL',-prices[it])
        if kind=='impact':
            p1=_r37_market_price(it,inv[it]+n if op=='SELL' else inv[it]-n,params)
            return (op!='SELL',-n*abs(prices[it]-p1))
        return (0,0)
    result=[]
    for kind in _QX_KINDS:
        group=rows if kind=='native' else sorted(rows,key=lambda o:rank(o,kind))
        out=[[] for _ in orders]
        for j,o in zip(ix,group):out[j]=o[:]
        result.append(out)
    return result

def _qx_before(obs):
    p=int(obs['player']);t=int(obs['step']);st=_QX_STATE.get(p)
    if st is None or t<=st['step']:
        st=_QX_STATE[p]={'step':-1,'receipt':None,'models':{}}
        if t==0:_QX_REPORT.update(changes=0,learned=0,ambiguous=0,errors=0,records=[])
    prev=st.get('receipt');st['receipt']=None;st['step']=t
    if not prev or prev['step']!=t-1 or prev['step']%24==23:return st
    # A receipt is usable only when all own signed quantities were fulfilled.
    now=obs['private'];net=prev['net'];enemy={};draw=_or2_draw(prev['shops'],prev['step'])
    for it,q in net.items():
        if int(now['shed'].get(it,0))!=prev['stock'].get(it,0)-q:return st
        r=int(obs['market']['inventory'][it])-prev['inv'][it]+draw.get(it,0)-q
        if abs(r)>100 or (r*q<0) or prev['prices'][it]<=1 or obs['market']['prices'][it]<=1:return st
        enemy[it]=r
    f=obs['farms'][p]
    if int(f['hires_today'])!=prev['hires_target']:return st
    if _hm_clean(now['seeds'])!=_hm_clean(prev['seeds_target']):return st
    actual=float(f['money'])-prev['cash']+prev['fixed']
    po={'market':{'prices':prev['prices'],'inventory':prev['inv']}}
    templates=_qx_templates(po,prev['native'],enemy);errors=[]
    for tpl in templates:
        their={it:max(0,q) for it,q in enemy.items()}
        a,b=_v44y_lockstep(prev['chosen'],tpl,prev['inv'],prev['stock'],their,prev['params'])
        errors.append(abs(a-actual))
    if not errors or min(errors)>2 or max(errors)-min(errors)<2:
        _QX_REPORT['ambiguous']+=1;return st
    model=st['models'].setdefault(prev['context'],{'w':[0.]*len(_QX_KINDS),'n':0})
    best=min(errors);scale=max(2.,abs(actual)*.003)
    model['w']=[max(-18.,.96*w-min(6.,(e-best)/scale)) for w,e in zip(model['w'],errors)]
    model['n']+=1;_QX_REPORT['learned']+=1
    return st

def _qx_finish(obs,action):
    p=int(obs['player']);t=int(obs['step']);st=_qx_before(obs)
    if not _QX_ENABLED or t<144 or _HM_STATES.get(p,{}).get('active'):return action
    original=[list(o) for o in action.get('market',[])];ix=_qx_rows(original)
    if len(ix)<2:return action
    # Current implementation leaves every non-trade slot fixed. A repeated
    # input round trip is also left to its existing dedicated controller.
    if any(sum(len(o)>2 and o[1]==it and o[0] in ('SELL','BUY_PRODUCT') and o[2]>0 for o in original)>1 for it in PRODUCTS):return action
    f,pr=_up_project(obs,action);stock=pr['shed'];params=_at_params(obs);inv=obs['market']['inventory']
    quantities={};net={}
    for j in ix:
        op,it,q=original[j];n=min(int(q),int(stock.get(it,0))) if op=='SELL' else int(q)
        if n<=0 or n>100:return action
        quantities[it]=n;net[it]=n if op=='SELL' else -n
    context='mixed' if any(q<0 for q in net.values()) else 'sales'
    model=st['models'].get(context,{'w':[0.]*len(_QX_KINDS),'n':0})
    exp=[math.exp(x-max(model['w'])) for x in model['w']];tot=sum(exp);conf=min(.85,model['n']/(model['n']+4))
    weights=[(1-conf)/len(exp)+conf*x/tot for x in exp]
    templates=_qx_templates(obs,original)
    # Use differing same-family lot sizes, not a claim about private stock.
    scenarios=[]
    for ratio,mass in ((1.,.6),(.5,.2),(1.5,.2)):
        for tpl,w in zip(templates,weights):
            arr=[(o[:2]+[max(1,min(100,round(quantities[o[1]]*ratio)))]) if o else [] for o in tpl]
            their={o[1]:o[2] for o in arr if o and o[0]=='SELL'}
            scenarios.append((arr,their,mass*w))
    mat=[];cache={}
    for j in ix:
        op,it,_=original[j];n=quantities[it];row=[]
        for k in ix:
            val=0.
            for tpl,their,w in scenarios:
                b=next((h for h,o in enumerate(tpl) if o and o[1]==it),j)
                eo=tpl[b] if b<len(tpl) else [];key=(it,op,n,k,tuple(eo),b)
                if key not in cache:
                    mine=[[] for _ in original];mine[k]=[op,it,n]
                    theirs=[[] for _ in original];theirs[b]=eo
                    cache[key]=_v44y_lockstep(mine,theirs,{it:inv[it]},{it:stock.get(it,0)},{it:their.get(it,0)},{it:params[it]})
                a,bval=cache[key];val+=w*(a-bval)
            row.append(val)
        mat.append(row)
    _,assignment=_sp_assign(mat,ix);chosen=[o[:] for o in original]
    for row,k in assignment:chosen[k]=original[ix[row]][:]
    out=action
    if chosen!=original:
        gs=[];own=[];valid=True
        _HM_ENGINE['_price_params']=params;_HM_ENGINE['_price_cache']={}
        for tpl,their,w in scenarios:
            # Exact joint cash, capacity and protected purchases for the own
            # account. Enemy stock here is a scenario, never real private data.
            pp=[None,None];pp[p]=pr;pp[1-p]={'shed':dict(their),'seeds':{},'inventories':[{} for _ in range(len(obs['farms'][1-p]['hands'])+1)]}
            ff=copy.deepcopy(obs['farms']);ff[p]=f
            aa=[None,None];aa[p]=action;aa[1-p]={'farmer':['PASS'],'hands':[],'market':tpl}
            snap=(ff,pp,aa);hyp={'cfg':{},'predicted':aa[1-p]}
            r0=_hm_settle(obs,snap,original,hyp);r1=_hm_settle(obs,snap,chosen,hyp)
            if not _hm_own_contract(r1,r0,p):valid=False;break
            gs.append((w,r1[0]-r0[0]));own.append((w,r1[1][p]['money']-r0[1][p]['money']))
        if valid and gs:
            gain=sum(w*g for w,g in gs);ogain=sum(w*g for w,g in own)
            # Keep a small worst-scenario loss budget instead of treating the
            # estimated likely opponent as certain.
            score=.8*gain+.2*min(g for w,g in gs)
            if score>1 and ogain>=0 and min(g for w,g in own)>=-12:
                out=dict(action,market=chosen);_QX_REPORT['changes']+=1
                if len(_QX_REPORT['records'])<200:_QX_REPORT['records'].append(dict(step=t,context=context,samples=model['n'],score=score,mean_gain=gain,worst_own=min(g for w,g in own),before=original,after=chosen,weights=weights))
    # Record only orders whose fixed expenses can be unambiguously reconciled.
    orders=out['market'];fixed=0;hn=f['hires_today'];seeds=dict(pr['seeds']);clean=True
    for o in orders:
        if not o:continue
        if o[0]=='HIRE':fixed+=_v219_fib(hn);hn+=1
        elif len(o)>2 and o[0]=='BUY_SEED':fixed+=SEED_PRICE[o[1]]*o[2];seeds[o[1]]=seeds.get(o[1],0)+o[2]
        elif o[0] in ('BUY_LAND','BUY_ANIMAL'):clean=False
    if clean:
        st['receipt']={'step':t,'context':context,'native':original,'chosen':orders,'net':net,'stock':dict(stock),'inv':dict(inv),'prices':dict(obs['market']['prices']),'params':params,'cash':f['money'],'fixed':fixed,'hires_target':hn,'seeds_target':seeds,'shops':obs['town']['unlocked_shops'][:]}
    return out

# At the $1 floor the rules do not add inventory to the market. Dumping such
# a unit cannot suppress the opponent's price further. Retain a small physical
# lot when space/cash permits; sell at recovery or mandatory deadline.
_FO_STATE={}
_FO_REPORT={'deferred':0,'released':0,'forced':0,'errors':0,'records':[]}
def _fo_apply(obs,action):
    p=int(obs['player']);t=int(obs['step']);st=_FO_STATE.get(p)
    if st is None or t<=st['step']:
        st=_FO_STATE[p]={'step':-1,'lots':{}}
        if t==0:_FO_REPORT.update(deferred=0,released=0,forced=0,errors=0,records=[])
    st['step']=t
    if t<144 or _HM_STATES.get(p,{}).get('active'):return action
    orders=[list(o) for o in action.get('market',[])];f,pr=_up_project(obs,action)
    # Funding and materials come before the optional recovery position.
    funded=_r97_budget(obs,orders)
    stock=pr['shed'];total=sum(stock.values())+sum(sum(b.values()) for b in pr['inventories'])
    params=_at_params(obs);marketinv=obs['market']['inventory'];cashitems=('CARROT','TOMATO','STRAWBERRY','MELON','EGG','MILK','WOOL')
    # Reconsider real held lots each callback. Expiry never rolls forward.
    for it,lot in list(st['lots'].items()):
        lot['qty']=min(lot['qty'],max(0,int(stock.get(it,0))))
        if lot['qty']<=0:del st['lots'][it];continue
        queued=sum(max(0,int(o[2])) for o in orders if len(o)>2 and o[:2]==['SELL',it])
        force=t>=lot['until'] or t>=694 or total>=85 or not funded
        if (force or obs['market']['prices'][it]>1) and queued<lot['qty']:
            extra=lot['qty']-queued
            j=next((j for j,o in enumerate(orders) if len(o)>2 and o[:2]==['SELL',it]),None)
            if j is not None:orders[j][2]+=extra
            elif len(orders)<10:orders.append(['SELL',it,extra])
            if force:_FO_REPORT['forced']+=extra
    augmented=[o[:] for o in orders];left=dict(stock);buy_extra=sum(max(0,int(o[2])) for o in orders if len(o)>2 and o[0] in ('BUY_PRODUCT','BUY_ANIMAL'))
    sales={};retains={}
    _,_,actual_sale_slots=_r97_market_stock(stock,augmented)
    total_original_sold=sum(actual_sale_slots.values())
    # Cash-product-only retention. WHEAT/FERTILIZER are never held here.
    for j,o in enumerate(orders):
        if len(o)<3 or o[0]!='SELL':continue
        it=o[1];have=max(0,int(left.get(it,0)));q=min(have,max(0,int(o[2])));left[it]=have-q
        sales[it]=sales.get(it,0)+q
        if it not in cashitems or not q or t>=694 or not funded:continue
        lot=st['lots'].get(it)
        if lot and t>=lot['until']:continue
        inv=int(marketinv[it]);head=0
        for k in range(q):
            price=_r37_market_price(it,inv,params)
            if price<=1:break
            head+=1;inv+=1
        # Each lot has an exact lower-bound cash-out value of one per unit,
        # but no assumption is made that a price recovery will actually occur.
        tail=q-head
        # Original fulfilled sales, not oversized requested quantities, release room.
        room=max(0,80-(total+buy_extra-total_original_sold)-sum(retains.values()))
        keep=min(tail,room,12)
        if keep>0:orders[j][2]=q-keep;retains[it]=retains.get(it,0)+keep
    for it in set(st['lots'])|set(retains):
        old=st['lots'].get(it,{'qty':0,'until':min(694,t+24)})
        sold=sales.get(it,0);keep=retains.get(it,0)
        rem=max(0,old['qty']-sold)+keep
        _FO_REPORT['released']+=min(old['qty'],max(0,sold-keep))
        if rem:st['lots'][it]={'qty':rem,'until':old['until']}
        else:st['lots'].pop(it,None)
    if orders==action['market']:return action
    _FO_REPORT['deferred']+=sum(retains.values())
    if len(_FO_REPORT['records'])<200:_FO_REPORT['records'].append({'step':t,'held':retains,'before':action['market'],'after':orders,'total':total})
    return dict(action,market=orders)

_GR_REPORT={'errors':[],'changes':0}
def _gr_apply(obs,action):
    if int(obs['step'])==0:_GR_REPORT.update(errors=[],changes=0)
    if _HM_STATES.get(int(obs['player']),{}).get('active'):return action
    result=action
    try:
        cfg=_HM_BANK.get(int(obs['player']),{}).get('models',{})
        anycfg=next((st.get('cfg',{}) for st in cfg.values()),{})
        if anycfg.get('marketParams') or any(anycfg.get(k,v)!=v for k,v in (('boardSize',10),('turnsPerDay',24),('shedCapacity',100),('farmHandCostMult',1),('maxMarketOrdersPerTurn',10))):return action
        result=_fx_opening(obs,result)
        result=_fg_guard(obs,result)
        result=_fo_apply(obs,result)
        result=_qx_finish(obs,result)
        result=_js_finish(obs,result)
        _js_remember(obs,result)
    except Exception as exc:
        if len(_GR_REPORT['errors'])<20:_GR_REPORT['errors'].append([int(obs['step']),repr(exc)])
        return action
    if result!=action:
        _GR_REPORT['changes']+=1
        p=int(obs['player']);mp=_MP_STATE.get(p)
        if mp:mp['receipt']=None;mp['sp_receipt']=None
        if p in _AT_STATE:_at_remember(obs,result,_AT_STATE[p])
        _rp_remember(obs,result)
    return result


_WC_REPORT={'opening_changes':0,'net_wheat':0}
def _fx_opening(obs,action):
    # Buy opening operating input without an unidentifiable speculative cycle.
    if int(obs['step'])!=0:return action
    _WC_REPORT.update(opening_changes=0,net_wheat=0)
    rows=action.get('market',[])
    if len(rows)<2 or any(len(o)!=3 or o[1]!='WHEAT' or o[0] not in ('SELL','BUY_PRODUCT') or o[2]<0 for o in rows):return action
    if any(obs['private']['shed'].values()) or any(obs['private']['inventories']):return action
    net=sum(int(o[2])*(1 if o[0]=='BUY_PRODUCT' else -1) for o in rows)
    if not 0<net<=100 or not any(o[0]=='SELL' and o[2]>0 for o in rows):return action
    _WC_REPORT.update(opening_changes=1,net_wheat=net)
    return dict(action,market=[['BUY_PRODUCT','WHEAT',net]])

# Public-flow feedback: no opponent identity, replay or opponent private state.
_JS_STATE={}
_JS_REPORT={'changes':0,'samples':0,'censored':0,'errors':[],'records':[]}
_JS_CASH=('CARROT','TOMATO','STRAWBERRY','MELON','EGG','MILK','WOOL')
def _js_before(obs):
    p=int(obs['player']);t=int(obs['step']);st=_JS_STATE.get(p)
    if st is None or t<st['step'] or t==0 and st['step']!=0:
        st=_JS_STATE[p]={'step':-1,'receipt':None,'flow':{},'seen':{}}
        if t==0:_JS_REPORT.update(changes=0,samples=0,censored=0,errors=[],records=[])
    if st['step']==t:return st
    old=st.get('receipt');st['receipt']=None;st['step']=t
    if not old or old['step']!=t-1 or old['step']%24==23:return st
    draw=_or2_draw(old['shops'],old['step'])
    now=obs['private']['shed'];market=obs['market']
    for it in PRODUCTS:
        if old['prices'].get(it,0)<=1 or market['prices'].get(it,0)<=1:
            _JS_REPORT['censored']+=1;continue
        own=old['shed'].get(it,0)-now.get(it,0)
        flow=int(market['inventory'][it])-old['inventory'][it]+draw.get(it,0)-own
        if abs(flow)>100:continue
        v=st['flow'].setdefault(it,{'sell':0.,'buy':0.,'sell_count':0,'buy_count':0})
        if flow>0:
            v['sell']=float(flow) if not v['sell_count'] else .75*v['sell']+.25*flow
            v['sell_count']+=1
        elif flow<0:
            v['buy']=float(-flow) if not v['buy_count'] else .75*v['buy']-.25*flow
            v['buy_count']+=1
        st['seen'][it]=flow;_JS_REPORT['samples']+=1
    return st

def _js_remember(obs,action):
    st=_js_before(obs)
    _,pr=_up_project(obs,action)
    st['receipt']={'step':int(obs['step']),'shed':dict(pr['shed']),
                   'inventory':dict(obs['market']['inventory']),
                   'prices':dict(obs['market']['prices']),
                   'shops':list(obs['town']['unlocked_shops'])}

def _js_scenarios(obs,st,orders):
    p=int(obs['player']);counts={};animal_goods={'COW':'MILK','SHEEP':'WOOL','GOOSE':'EGG'}
    for row in obs['farms'][1-p]['tiles']:
        for z in row:
            if not isinstance(z,dict):continue
            it=z.get('crop') or animal_goods.get(z.get('animal'))
            if it:counts[it]=counts.get(it,0)+int(z.get('yield_units',0))
    stock=_OR2_STATE.get(p,{}).get('stock',{})
    qs={}
    for it in PRODUCTS:
        v=st['flow'].get(it,{})
        q=max(counts.get(it,0),stock.get(it,0),round(v.get('sell',0)))
        if q>0:qs[it]=min(64,int(q))
    if not qs:return []
    params=_at_params(obs);inv=obs['market']['inventory'];prices=obs['market']['prices']
    def impact(it):
        return qs[it]*abs(prices[it]-_r37_market_price(it,inv[it]+qs[it],params))
    rank=sorted(qs,key=lambda x:(-impact(x),-prices[x],x))
    pricey=sorted(qs,key=lambda x:(-prices[x],x))
    out=[([],{},.15)]
    for items,offset,mass,ratio in ((rank,0,.35,1.),(pricey,0,.20,.65),(rank,3,.15,1.),(rank,0,.15,1.4)):
        rows=[[] for _ in range(offset)]
        for it in items[:10-offset]:rows.append(['SELL',it,min(90,max(1,round(qs[it]*ratio)))])
        out.append((rows,{o[1]:o[2] for o in rows if o},mass))
    return out

def _js_finish(obs,action):
    st=_js_before(obs);p=int(obs['player']);t=int(obs['step'])
    if t<144 or _HM_STATES.get(p,{}).get('active'):return action
    orders=[list(o) for o in action.get('market',[])]
    sell=[j for j,o in enumerate(orders) if len(o)>2 and o[0]=='SELL' and o[2]>0]
    repeat=any(sum(len(o)>2 and o[0] in ('SELL','BUY_PRODUCT') and o[1]==it and o[2]>0 for o in orders)>1 for it in ('WHEAT','FERTILIZER'))
    if not repeat or len(sell)<2 or not any(orders[j][1] in _JS_CASH for j in sell):return action
    scenarios=_js_scenarios(obs,st,orders)
    if not scenarios:return action
    f,pr=_up_project(obs,action);params=_at_params(obs);inv=obs['market']['inventory']
    candidates=[]
    for n,i in enumerate(sell):
        for j in sell[n+1:]:
            if orders[i][1]==orders[j][1] or not (orders[i][1] in _JS_CASH or orders[j][1] in _JS_CASH):continue
            oo=[o[:] for o in orders];oo[i],oo[j]=oo[j],oo[i];candidates.append(oo)
    if not candidates:return action
    base=[_v44y_lockstep(orders,tpl,inv,pr['shed'],stock,params) for tpl,stock,mass in scenarios]
    ranked=[]
    for oo in candidates:
        vals=[];own=[]
        for (tpl,stock,mass),(a,b) in zip(scenarios,base):
            x,y=_v44y_lockstep(oo,tpl,inv,pr['shed'],stock,params)
            vals.append((mass,(x-y)-(a-b)));own.append((mass,x-a))
        score=.8*sum(w*x for w,x in vals)+.2*min(x for w,x in vals)
        if score>1 and sum(w*x for w,x in own)>=0 and min(x for w,x in own)>=-12:ranked.append((score,oo))
    if not ranked:return action
    _HM_ENGINE['_price_params']=params;_HM_ENGINE['_price_cache']={}
    for score,oo in sorted(ranked,key=lambda z:-z[0])[:2]:
        valid=True;gains=[];own=[]
        for tpl,stock,mass in scenarios:
            ff=copy.deepcopy(obs['farms']);ff[p]=f
            pp=[None,None];pp[p]=pr
            pp[1-p]={'shed':dict(stock),'seeds':{},'inventories':[{} for _ in range(len(ff[1-p]['hands'])+1)]}
            aa=[None,None];aa[p]=action;aa[1-p]={'farmer':['PASS'],'hands':[],'market':tpl}
            hyp={'cfg':{},'predicted':aa[1-p]};snap=(ff,pp,aa)
            b=_hm_settle(obs,snap,orders,hyp);n=_hm_settle(obs,snap,oo,hyp)
            if not _hm_own_contract(n,b,p):valid=False;break
            gains.append((mass,n[0]-b[0]));own.append((mass,n[1][p]['money']-b[1][p]['money']))
        if valid and gains:
            score=.8*sum(w*x for w,x in gains)+.2*min(x for w,x in gains)
            if score>1 and sum(w*x for w,x in own)>=0 and min(x for w,x in own)>=-12:
                _JS_REPORT['changes']+=1
                if len(_JS_REPORT['records'])<160:_JS_REPORT['records'].append({'step':t,'score':score,'before':orders,'after':oo})
                return dict(action,market=oo)
    return action

# Local native-cycle comparison; retains original feed/seed/worker safeguards.
_CX_REPORT={'windows':0,'eligible':0,'seed_targets':0}
def _cx_window(obs,action):
    t=int(obs['step']);p=int(obs['player']);d=t//24
    if t==0:_CX_REPORT.update(windows=0,eligible=0,seed_targets=0)
    if not 6<=d<=28:return (False,0)
    pc=int(obs['market']['prices'].get('CARROT',0));pw=int(obs['market']['prices'].get('WHEAT',0))
    if 4*pc-20<=pw-10+_CA_MARGIN:return (False,0)
    f=obs['farms'][p];positions=[list(f['farmer'])]+[list(x) for x in f['hands']]
    choices=[];seen=set()
    for s in range(t,min(672,t+24)+1):
        a=action if s==t else _ca_tape(p,s)
        commands=[a.get('farmer') or ['PASS']]+list(a.get('hands') or [])
        for i,pos in enumerate(positions):
            cmd=commands[i] if i<len(commands) else ['PASS']
            if cmd[:2]==['PLANT','WHEAT']:
                key=(tuple(pos),s//24)
                if key not in seen:seen.add(key);choices.append((s,tuple(pos)))
            if cmd and cmd[0] in _CA_MOVES:
                dx,dy=_CA_MOVES[cmd[0]];positions[i]=[max(0,min(9,pos[0]+dx)),max(0,min(9,pos[1]+dy))]
        for o in a.get('market',[]):
            if o and o[0]=='HIRE':positions.append(_ca_spawn(positions,10))
        if s%24==23:positions=[[4,4]]
    target=0
    for s,pos in choices:
        born=s//24
        visits=_ca_visits(obs,action,pos,min(718,(born+6)*24),start=s+1)
        wu,_,_=_ca_yield_path('WHEAT',born,visits)
        ch,cr,_=_ca_yield_path('CARROT',born,visits)
        cu=max(ch,cr if _CA_RESCUE else 0)
        if wu>0 and cu>0 and cu*(pc-_CA_DROP)-20>wu*pw-10+_CA_MARGIN:
            target+=1
            if target>=4:break
    _CX_REPORT['windows']+=1
    if target:_CX_REPORT['eligible']+=1
    return target>0,target


def agent(observation, configuration=None):
    _hm_before(observation,configuration)
    _up_begin(observation)
    original = _SC_PARENT(observation, configuration)
    step = int(observation['step'])
    seat = int(observation['player'])
    state = _SC_STATE.get(seat)
    if state is None or step <= state['step']:
        state = _SC_STATE[seat] = {'step': -1, 'plan': None}
        _SC_REPORT.update(proposed=0, bought=0, picked=0, placed=0,
                          aborted=0, events=[])
    state['step'] = step
    action = dict(original,
                  farmer=list(original.get('farmer') or ['PASS']),
                  hands=[list(cmd) for cmd in original.get('hands', [])],
                  market=[list(row) for row in original.get('market', [])])
    plan = state['plan']
    if plan is None:
        plan = _sc_plan(observation, action)
        if plan is not None:
            row = action['market'][plan['order']]
            action['market'][plan['order']] = ['BUY_ANIMAL', 'COW', 1]
            action['market'].insert(plan['order'] + 1,
                                    ['BUY_ANIMAL', 'SHEEP', row[2] - 1])
            state['plan'] = plan
            _SC_REPORT['proposed'] += 1
            _SC_REPORT['events'].append((step, 'proposed', plan['pos']))
        return _hm_finish(observation, _up_finish(observation, action))
    _sc_reconcile(observation, plan)
    actor = plan['actor']
    commands = [action['farmer']] + action['hands']
    if actor >= len(commands):
        return _hm_finish(observation, _up_finish(observation, action))
    if step == plan['pickup_step'] and plan['status'] == 'bought':
        if commands[actor][:2] == ['PICKUP', 'SHEEP'] and observation['private']['shed'].get('COW', 0):
            commands[actor] = ['PICKUP', 'COW']
            plan['status'] = 'pickup_sent'
    elif step == plan['place_step'] and plan['status'] == 'picked':
        farm = observation['farms'][seat]
        pos = tuple(farm['farmer'] if actor == 0 else farm['hands'][actor - 1])
        tile = farm['tiles'][pos[1]][pos[0]]
        bag = observation['private']['inventories'][actor]
        if (pos == plan['pos'] and commands[actor][:2] == ['PLACE', 'SHEEP']
                and isinstance(tile, dict) and tile.get('kind') == 'PASTURE'
                and bag.get('COW', 0)):
            commands[actor] = ['PLACE', 'COW']
            plan['status'] = 'place_sent'
    action['farmer'] = commands[0]
    action['hands'] = commands[1:]
    return _hm_finish(observation, _up_finish(observation, action))



agent.telemetry = _SC_REPORT
